window.CLO_SEARCH_INDEX=[{"page":"chapter-01/index.html","ordinal":12,"anchor":"search-entry-12","zh":"第一章｜从基础设置开始，认识 CLO3D 工作界面、3D 视角操作与二维、三维、缝纫工具。配合实机截图和录屏逐步练习。","en":"Chapter 01 — Learn basic settings, the CLO workspace, 3D view navigation, and essential 2D, 3D, and sewing tools.","headingZh":"CLO3D 第一章","headingEn":"CLO3D Chapter 01"},{"page":"chapter-01/index.html","ordinal":15,"anchor":"search-entry-15","zh":"一些基础设置","en":"Basic settings","headingZh":"一些基础设置","headingEn":"Basic settings"},{"page":"chapter-01/index.html","ordinal":16,"anchor":"search-entry-16","zh":"正式操作前，先学会切换界面语言，并记住工具栏或工作窗口消失时的恢复方法。以下截图来自本机 CLO 中文界面。","en":"Before you begin, learn how to change the interface language and restore a missing toolbar or work window. The screenshots show CLO in Chinese on this computer.","headingZh":"一些基础设置","headingEn":"Basic settings"},{"page":"chapter-01/index.html","ordinal":17,"anchor":"search-entry-17","zh":"如何更改语言","en":"Change the interface language","headingZh":"如何更改语言","headingEn":"Change the interface language"},{"page":"chapter-01/index.html","ordinal":18,"anchor":"search-entry-18","zh":"点击顶部菜单「设置」→「语言」，再选择需要的语言。选好后退出并重新启动 CLO，界面语言才会切换。","en":"From the top menu, choose Settings → Language, then select the language you want. Quit and restart CLO for the interface language to change.","headingZh":"如何更改语言","headingEn":"Change the interface language"},{"page":"chapter-01/index.html","ordinal":19,"anchor":"search-entry-19","zh":"图 1｜设置 → 语言；更改后需要重启 CLO","en":"Figure 1 | Settings → Language; restart CLO after changing it","headingZh":"如何更改语言","headingEn":"Change the interface language"},{"page":"chapter-01/index.html","ordinal":20,"anchor":"search-entry-20","zh":"找回工具栏与工作窗口","en":"Restore toolbars and work windows","headingZh":"找回工具栏与工作窗口","headingEn":"Restore toolbars and work windows"},{"page":"chapter-01/index.html","ordinal":21,"anchor":"search-entry-21","zh":"如果工具栏不见了，点击顶部「设置」→「显示」，进入「3D 工具栏」或「2D 工具栏」的子菜单，开启需要的工具栏。","en":"If a toolbar disappears, open Settings → Display from the top menu. Use the 3D Toolbar or 2D Toolbar submenu to show the toolbar you need.","headingZh":"找回工具栏与工作窗口","headingEn":"Restore toolbars and work windows"},{"page":"chapter-01/index.html","ordinal":22,"anchor":"search-entry-22","zh":"如果 3D 或 2D 工作窗口不见了，继续进入「窗口」，勾选「3D 视窗」或「2D 板片视窗」。如果整个布局乱了，可点击该菜单底部的「重置画面」。","en":"If the 3D or 2D work window disappears, open Window and enable 3D Window or 2D Pattern Window. If the entire layout is misplaced, choose Reset Screen at the bottom of this menu.","headingZh":"找回工具栏与工作窗口","headingEn":"Restore toolbars and work windows"},{"page":"chapter-01/index.html","ordinal":23,"anchor":"search-entry-23","zh":"图 2｜设置 → 显示 → 窗口；底部可重置画面","en":"Figure 2 | Settings → Display → Window; Reset Screen is at the bottom","headingZh":"找回工具栏与工作窗口","headingEn":"Restore toolbars and work windows"},{"page":"chapter-01/index.html","ordinal":24,"anchor":"search-entry-24","zh":"认识工作界面","en":"Explore the interface","headingZh":"认识工作界面","headingEn":"Explore the interface"},{"page":"chapter-01/index.html","ordinal":25,"anchor":"search-entry-25","zh":"CLO3D 的工作主要在 3D 窗口和 2D 版片窗口之间进行。资源库、对象列表和属性编辑器分布在两侧。先认清各区域，再开始画版。","en":"Most CLO3D work moves between the 3D Garment Window and the 2D Pattern Window. The Library, object list, and Property Editor sit around them. Locate these areas before you draw patterns.","headingZh":"认识工作界面","headingEn":"Explore the interface"},{"page":"chapter-01/index.html","ordinal":26,"anchor":"search-entry-26","zh":"图 1｜本机 CLO 2025 的真实工作界面。点击图片可以放大查看。","en":"Figure 1 | The actual CLO 2025 workspace on this computer. Click to view full size.","headingZh":"认识工作界面","headingEn":"Explore the interface"},{"page":"chapter-01/index.html","ordinal":31,"anchor":"search-entry-31","zh":"如何添加虚拟数字模特","en":"How to add a virtual avatar","headingZh":"如何添加虚拟数字模特","headingEn":"How to add a virtual avatar"},{"page":"chapter-01/index.html","ordinal":32,"anchor":"search-entry-32","zh":"先在 3D 窗口加入模特，再围绕模特安排版片。下面四步使用本机 CLO 2025 的真实操作截图。","en":"Add an avatar to the 3D window before arranging pattern pieces around it. The four steps below use actual CLO 2025 screenshots.","headingZh":"如何添加虚拟数字模特","headingEn":"How to add a virtual avatar"},{"page":"chapter-01/index.html","ordinal":33,"anchor":"search-entry-33","zh":"打开添加模特的菜单","en":"Open the Add Avatar menu","headingZh":"打开添加模特的菜单","headingEn":"Open the Add Avatar menu"},{"page":"chapter-01/index.html","ordinal":34,"anchor":"search-entry-34","zh":"在顶部菜单依次点击「文件」→「增加」→「虚拟模特」。此时会打开模特文件选择窗口。","en":"From the top menu, choose File → Add → Avatar. The avatar file picker will open.","headingZh":"打开添加模特的菜单","headingEn":"Open the Add Avatar menu"},{"page":"chapter-01/index.html","ordinal":35,"anchor":"search-entry-35","zh":"图 2｜文件 → 增加 → 虚拟模特","en":"Figure 2 | File → Add → Avatar","headingZh":"打开添加模特的菜单","headingEn":"Open the Add Avatar menu"},{"page":"chapter-01/index.html","ordinal":36,"anchor":"search-entry-36","zh":"选择需要的模特类型","en":"Choose an avatar category","headingZh":"选择需要的模特类型","headingEn":"Choose an avatar category"},{"page":"chapter-01/index.html","ordinal":37,"anchor":"search-entry-37","zh":"在 Avatar 文件夹中选择想要的类别，例如 Female、Male、Kid 或 Mannequin。不同电脑的 CLO 版本、安装资源和文件夹内容可能不同，以自己看到的文件为准。","en":"In the Avatar folder, choose a category such as Female, Male, Kid, or Mannequin. Folder names and available files can vary with the CLO version and installed assets.","headingZh":"选择需要的模特类型","headingEn":"Choose an avatar category"},{"page":"chapter-01/index.html","ordinal":38,"anchor":"search-entry-38","zh":"图 3｜选择一个模特类别；文件夹内容因电脑而异","en":"Figure 3 | Choose a category; folders vary by computer","headingZh":"选择需要的模特类型","headingEn":"Choose an avatar category"},{"page":"chapter-01/index.html","ordinal":39,"anchor":"search-entry-39","zh":"打开 .avt 模特文件","en":"Open an .avt avatar file","headingZh":"打开 .avt 模特文件","headingEn":"Open an .avt avatar file"},{"page":"chapter-01/index.html","ordinal":40,"anchor":"search-entry-40","zh":"进入所选类别后，找到扩展名为 .avt 的模特文件。图中 FV2.1_Mia.avt 只是示例；双击你想用的 .avt 文件，或选中后点击「打开」。","en":"Inside the chosen category, find a file ending in .avt. FV2.1_Mia.avt is only an example; double-click your chosen file or select it and click Open.","headingZh":"打开 .avt 模特文件","headingEn":"Open an .avt avatar file"},{"page":"chapter-01/index.html","ordinal":41,"anchor":"search-entry-41","zh":"图 4｜选择扩展名为 .avt 的文件","en":"Figure 4 | Open a file ending in .avt","headingZh":"打开 .avt 模特文件","headingEn":"Open an .avt avatar file"},{"page":"chapter-01/index.html","ordinal":42,"anchor":"search-entry-42","zh":"确认模特加载成功","en":"Check the loaded avatar","headingZh":"确认模特加载成功","headingEn":"Check the loaded avatar"},{"page":"chapter-01/index.html","ordinal":43,"anchor":"search-entry-43","zh":"返回 CLO 的 3D 窗口。看到模特出现在工作区，就说明添加成功；图中展示的是其中一个女性模特。","en":"Return to CLO's 3D window. The avatar appearing in the workspace confirms that it loaded successfully. The picture shows one example female avatar.","headingZh":"确认模特加载成功","headingEn":"Check the loaded avatar"},{"page":"chapter-01/index.html","ordinal":44,"anchor":"search-entry-44","zh":"图 5｜模特出现在 3D 窗口中","en":"Figure 5 | The avatar appears in the 3D window","headingZh":"确认模特加载成功","headingEn":"Check the loaded avatar"},{"page":"chapter-01/index.html","ordinal":45,"anchor":"search-entry-45","zh":"鼠标与视角操作","en":"Mouse and view controls","headingZh":"鼠标与视角操作","headingEn":"Mouse and view controls"},{"page":"chapter-01/index.html","ordinal":46,"anchor":"search-entry-46","zh":"在 3D 窗口中，先学会移动观察视角，再开始摆放版片。下面四段录屏分别演示平移、旋转、缩放和数字键切换视角；播放时可以暂停并跟着操作。","en":"Learn to navigate the 3D window before placing pattern pieces. These four recordings show panning, rotating, zooming, and switching views with number keys. Pause each clip and practice along.","headingZh":"鼠标与视角操作","headingEn":"Mouse and view controls"},{"page":"chapter-01/index.html","ordinal":47,"anchor":"search-entry-47","zh":"平移视角","en":"Pan the view","headingZh":"平移视角","headingEn":"Pan the view"},{"page":"chapter-01/index.html","ordinal":48,"anchor":"search-entry-48","zh":"按住鼠标滚轮（中键），上下拖动鼠标，就能平移 3D 画面。这个操作需要可按下的滚轮；Apple Magic Mouse 没有中键，不能直接使用此按法。","en":"Hold down the mouse wheel (middle button) and drag up or down to pan the 3D view. This requires a clickable wheel; the Apple Magic Mouse has no middle button.","headingZh":"平移视角","headingEn":"Pan the view"},{"page":"chapter-01/index.html","ordinal":50,"anchor":"search-entry-50","zh":"旋转视角","en":"Rotate the view","headingZh":"旋转视角","headingEn":"Rotate the view"},{"page":"chapter-01/index.html","ordinal":51,"anchor":"search-entry-51","zh":"按住鼠标右键并拖动鼠标，视角会围绕世界中心旋转。试着从模特正面转到侧面，再转回来。","en":"Hold the right mouse button and drag to rotate the view around the world center. Try turning from the avatar's front to its side and back.","headingZh":"旋转视角","headingEn":"Rotate the view"},{"page":"chapter-01/index.html","ordinal":53,"anchor":"search-entry-53","zh":"缩放画面","en":"Zoom the view","headingZh":"缩放画面","headingEn":"Zoom the view"},{"page":"chapter-01/index.html","ordinal":54,"anchor":"search-entry-54","zh":"滚动鼠标滚轮，可以放大或缩小 3D 画面。缩放以画面中心为基准；模特偏离中心时，先平移视角再缩放。","en":"Scroll the mouse wheel to zoom in or out. Zooming uses the center of the screen, so pan first if the avatar is off center.","headingZh":"缩放画面","headingEn":"Zoom the view"},{"page":"chapter-01/index.html","ordinal":56,"anchor":"search-entry-56","zh":"数字键切换视角","en":"Switch views with number keys","headingZh":"数字键切换视角","headingEn":"Switch views with number keys"},{"page":"chapter-01/index.html","ordinal":57,"anchor":"search-entry-57","zh":"按数字键 1–6，可以快速切换预设视角；按 2 可回到模特正面。","en":"Press number keys 1–6 to switch between preset views. Key 2 returns to the avatar’s front view.","headingZh":"数字键切换视角","headingEn":"Switch views with number keys"},{"page":"chapter-01/index.html","ordinal":58,"anchor":"search-entry-58","zh":"如果 3D 窗口里突然看不到物体，或旋转后找不到方向，先用这些数字键找回熟悉的观察角度。","en":"If an object disappears from view or you lose your orientation, use these keys to return to a familiar angle.","headingZh":"数字键切换视角","headingEn":"Switch views with number keys"},{"page":"chapter-01/index.html","ordinal":60,"anchor":"search-entry-60","zh":"二维版片工具","en":"Essential 2D pattern tools","headingZh":"二维版片工具","headingEn":"Essential 2D pattern tools"},{"page":"chapter-01/index.html","ordinal":61,"anchor":"search-entry-61","zh":"先认清真实图标或菜单位置，再跟着录屏操作。本章已加入整片调整、点线编辑、曲线与加点演示；其他工具保留本机 CLO 2025.0.128 中文菜单截图。","en":"Identify each tool from its actual CLO icon or menu capture, then follow the recordings. This chapter now includes demonstrations of whole-pattern moves, point-and-line edits, curves, and added points. Other tools retain menu captures from CLO 2025.0.128 in Chinese.","headingZh":"二维版片工具","headingEn":"Essential 2D pattern tools"},{"page":"chapter-01/index.html","ordinal":62,"anchor":"search-entry-62","zh":"先认识二维版片窗口","en":"First, locate the 2D Pattern Window","headingZh":"先认识二维版片窗口","headingEn":"First, locate the 2D Pattern Window"},{"page":"chapter-01/index.html","ordinal":63,"anchor":"search-entry-63","zh":"画版之前，先认清二维窗口里的两个位置：右侧工具栏，以及中央的模特剪影。点击图片可以放大查看。","en":"Before drafting, find two landmarks in the 2D window: the toolbar on the right and the avatar silhouette in the center. Click either image to enlarge it.","headingZh":"先认识二维版片窗口","headingEn":"First, locate the 2D Pattern Window"},{"page":"chapter-01/index.html","ordinal":64,"anchor":"search-entry-64","zh":"图 1｜二维版片工具栏","en":"Figure 1 | 2D pattern toolbar","headingZh":"先认识二维版片窗口","headingEn":"First, locate the 2D Pattern Window"},{"page":"chapter-01/index.html","ordinal":66,"anchor":"search-entry-66","zh":"图 2｜与模特同步的剪影","en":"Figure 2 | Avatar silhouette","headingZh":"先认识二维版片窗口","headingEn":"First, locate the 2D Pattern Window"},{"page":"chapter-01/index.html","ordinal":68,"anchor":"search-entry-68","zh":"读懂工具图标，画出第一块版片","en":"Read the tool icons and draw your first pattern","headingZh":"读懂工具图标，画出第一块版片","headingEn":"Read the tool icons and draw your first pattern"},{"page":"chapter-01/index.html","ordinal":69,"anchor":"search-entry-69","zh":"先学会展开工具组，再跟着视频画一个矩形。","en":"First, learn to expand a tool group. Then follow the video to draw a rectangle.","headingZh":"读懂工具图标，画出第一块版片","headingEn":"Read the tool icons and draw your first pattern"},{"page":"chapter-01/index.html","ordinal":70,"anchor":"search-entry-70","zh":"图 1｜小三角表示还有其他工具","en":"Figure 1 | The triangle marks a tool group","headingZh":"读懂工具图标，画出第一块版片","headingEn":"Read the tool icons and draw your first pattern"},{"page":"chapter-01/index.html","ordinal":72,"anchor":"search-entry-72","zh":"图 2｜长按后展开小菜单","en":"Figure 2 | The expanded tool menu","headingZh":"读懂工具图标，画出第一块版片","headingEn":"Read the tool icons and draw your first pattern"},{"page":"chapter-01/index.html","ordinal":74,"anchor":"search-entry-74","zh":"跟着视频创建矩形","en":"Draw a rectangle with the video","headingZh":"跟着视频创建矩形","headingEn":"Draw a rectangle with the video"},{"page":"chapter-01/index.html","ordinal":75,"anchor":"search-entry-75","zh":"录屏同时显示左侧 3D 窗口和右侧 2D 窗口。可以暂停或全屏播放，边看边做。","en":"The recording shows the 3D window on the left and the 2D window on the right. Pause or use full screen while you follow along.","headingZh":"跟着视频创建矩形","headingEn":"Draw a rectangle with the video"},{"page":"chapter-01/index.html","ordinal":76,"anchor":"search-entry-76","zh":"在 2D 窗口右侧工具栏，按住绘图工具图标，展开包含「多边形」「矩形」等选项的小菜单，然后点击「矩形」。","en":"In the 2D toolbar, press and hold the shape tool to open its menu, then choose Rectangle.","headingZh":"跟着视频创建矩形","headingEn":"Draw a rectangle with the video"},{"page":"chapter-01/index.html","ordinal":77,"anchor":"search-entry-77","zh":"在 2D 工作区选定起点，按住鼠标左键向右下方拖动；松开鼠标，矩形版片就创建好了。","en":"Choose a starting point in the 2D workspace. Hold the left mouse button and drag down and right, then release to create the rectangular pattern.","headingZh":"跟着视频创建矩形","headingEn":"Draw a rectangle with the video"},{"page":"chapter-01/index.html","ordinal":78,"anchor":"search-entry-78","zh":"看向左侧 3D 窗口：同一块矩形版片会出现在模特附近。录屏最后还旋转了视角，从侧面查看版片。","en":"Look at the 3D window on the left: the same rectangular pattern appears near the avatar. At the end, the view rotates to show the piece from the side.","headingZh":"跟着视频创建矩形","headingEn":"Draw a rectangle with the video"},{"page":"chapter-01/index.html","ordinal":79,"anchor":"search-entry-79","zh":"打开绘图工具组，选择矩形，在二维工作区拖动画出版片","en":"Open the shape tools, choose Rectangle, and drag in the 2D workspace","headingZh":"跟着视频创建矩形","headingEn":"Draw a rectangle with the video"},{"page":"chapter-01/index.html","ordinal":80,"anchor":"search-entry-80","zh":"观察 2D 与 3D 的对应关系","en":"Notice how the 2D and 3D views correspond","headingZh":"跟着视频创建矩形","headingEn":"Draw a rectangle with the video"},{"page":"chapter-01/index.html","ordinal":81,"anchor":"search-entry-81","zh":"矩形在右侧 2D 工作区生成的同时，也会在左侧 3D 窗口出现。它在 2D 中相对模特剪影的摆放位置，对应着 3D 中相对模特的位置；从不同角度看，版片的外观会因透视而变化。","en":"The rectangle appears in the 3D window as soon as it is created in 2D. Its placement relative to the 2D avatar silhouette corresponds to its position around the 3D avatar. Perspective can make the piece look different from another viewing angle.","headingZh":"跟着视频创建矩形","headingEn":"Draw a rectangle with the video"},{"page":"chapter-01/index.html","ordinal":82,"anchor":"search-entry-82","zh":"先分清：整片，还是点和线？","en":"First choose: whole piece, or points and lines?","headingZh":"跟着视频创建矩形","headingEn":"Draw a rectangle with the video"},{"page":"chapter-01/index.html","ordinal":83,"anchor":"search-entry-83","zh":"「调整板片」（A）选择并移动整块版片；「编辑板片」（Z）只调整选中的点或线，改变局部轮廓。","en":"Transform Pattern (A) selects and moves the whole piece. Edit Pattern (Z) changes selected points or lines to reshape its outline.","headingZh":"跟着视频创建矩形","headingEn":"Draw a rectangle with the video"},{"page":"chapter-01/index.html","ordinal":86,"anchor":"search-entry-86","zh":"调整板片","en":"Transform Pattern","headingZh":"调整板片","headingEn":"Transform Pattern"},{"page":"chapter-01/index.html","ordinal":88,"anchor":"search-entry-88","zh":"Transform Pattern","en":"Transform Pattern","headingZh":"调整板片","headingEn":"Transform Pattern"},{"page":"chapter-01/index.html","ordinal":89,"anchor":"search-entry-89","zh":"2D → 编辑 → 调整板片","en":"2D → Edit → Transform Pattern","headingZh":"调整板片","headingEn":"Transform Pattern"},{"page":"chapter-01/index.html","ordinal":90,"anchor":"search-entry-90","zh":"选中整块版片，整体移动、旋转或缩放；不单独改变某个点或一条边。","en":"Select the whole pattern to move, rotate, or scale it without editing an individual point or edge.","headingZh":"调整板片","headingEn":"Transform Pattern"},{"page":"chapter-01/index.html","ordinal":91,"anchor":"search-entry-91","zh":"按 A，点击版片内部；整片高亮，周围出现选框。","en":"Press A and click inside the pattern. The whole piece highlights and a bounding box appears.","headingZh":"调整板片","headingEn":"Transform Pattern"},{"page":"chapter-01/index.html","ordinal":92,"anchor":"search-entry-92","zh":"按住鼠标左键拖动，整块版片一起移动，原来的矩形轮廓不变。","en":"Hold the left mouse button and drag. The whole piece moves without changing its rectangular outline.","headingZh":"调整板片","headingEn":"Transform Pattern"},{"page":"chapter-01/index.html","ordinal":93,"anchor":"search-entry-93","zh":"只想修改一个角点或一条边？改用「编辑板片」（Z）。","en":"To change one corner or edge, use Edit Pattern (Z).","headingZh":"调整板片","headingEn":"Transform Pattern"},{"page":"chapter-01/index.html","ordinal":97,"anchor":"search-entry-97","zh":"编辑板片","en":"Edit Pattern","headingZh":"编辑板片","headingEn":"Edit Pattern"},{"page":"chapter-01/index.html","ordinal":99,"anchor":"search-entry-99","zh":"Edit Pattern","en":"Edit Pattern","headingZh":"编辑板片","headingEn":"Edit Pattern"},{"page":"chapter-01/index.html","ordinal":100,"anchor":"search-entry-100","zh":"2D → 编辑 → 编辑板片","en":"2D → Edit → Edit Pattern","headingZh":"编辑板片","headingEn":"Edit Pattern"},{"page":"chapter-01/index.html","ordinal":101,"anchor":"search-entry-101","zh":"选择版片轮廓上的点或线。选中后目标会高亮，拖动它就能改变局部形状。","en":"Select a point or line on the pattern outline. The selection highlights; drag it to reshape that part of the pattern.","headingZh":"编辑板片","headingEn":"Edit Pattern"},{"page":"chapter-01/index.html","ordinal":102,"anchor":"search-entry-102","zh":"按 Z，点击一个角点；高亮后拖动，只改变这个角的位置。","en":"Press Z and click a corner point. Once highlighted, drag it to move that corner.","headingZh":"编辑板片","headingEn":"Edit Pattern"},{"page":"chapter-01/index.html","ordinal":103,"anchor":"search-entry-103","zh":"也可以点击一条边；边线高亮后拖动，调整这段轮廓。","en":"You can also click an edge. Drag the highlighted line to adjust that part of the outline.","headingZh":"编辑板片","headingEn":"Edit Pattern"},{"page":"chapter-01/index.html","ordinal":104,"anchor":"search-entry-104","zh":"需要精确数值时，选中目标并开始拖动；拖动过程中按鼠标右键，再输入需要的数值。","en":"For an exact value, start dragging the selected point or line, then press the right mouse button while dragging and enter the value.","headingZh":"编辑板片","headingEn":"Edit Pattern"},{"page":"chapter-01/index.html","ordinal":106,"anchor":"search-entry-106","zh":"V、C、X：三个不同的动作","en":"V, C, X: three different actions","headingZh":"编辑板片","headingEn":"Edit Pattern"},{"page":"chapter-01/index.html","ordinal":107,"anchor":"search-entry-107","zh":"V 在线段上拖出曲线点；C 直接拖动一段线或弧线；X 在边线上添加新点。它们都从右侧编辑工具的小菜单中选择。","en":"V pulls a curve point from a segment; C drags a line or arc to change its bend; X adds a new point on an edge. All three are in the editing-tool flyout.","headingZh":"编辑板片","headingEn":"Edit Pattern"},{"page":"chapter-01/index.html","ordinal":110,"anchor":"search-entry-110","zh":"编辑曲线点","en":"Edit Curve Point","headingZh":"编辑曲线点","headingEn":"Edit Curve Point"},{"page":"chapter-01/index.html","ordinal":112,"anchor":"search-entry-112","zh":"Edit Curve Point","en":"Edit Curve Point","headingZh":"编辑曲线点","headingEn":"Edit Curve Point"},{"page":"chapter-01/index.html","ordinal":113,"anchor":"search-entry-113","zh":"2D → 编辑 → 编辑曲线点","en":"2D → Edit → Edit Curve Point","headingZh":"编辑曲线点","headingEn":"Edit Curve Point"},{"page":"chapter-01/index.html","ordinal":114,"anchor":"search-entry-114","zh":"只在线段上操作。拖动线上的曲线点，可将直边拉成弧线，并控制弧线形状。","en":"Work on a pattern edge: drag a curve point on the segment to bend a straight edge into a curve and shape the arc.","headingZh":"编辑曲线点","headingEn":"Edit Curve Point"},{"page":"chapter-01/index.html","ordinal":115,"anchor":"search-entry-115","zh":"长按右侧的编辑工具图标，在小菜单中选择「编辑曲线点」（V）。","en":"Press and hold the editing-tool icon on the right, then choose Edit Curve Point (V) from its flyout.","headingZh":"编辑曲线点","headingEn":"Edit Curve Point"},{"page":"chapter-01/index.html","ordinal":116,"anchor":"search-entry-116","zh":"将鼠标移到要弯曲的线段。看到红色提示点后，按住左键向外拖动；蓝色预览线显示弧度，松开后曲线成形。","en":"Move over the segment until a red guide point appears. Hold the left button and drag outward; the blue preview shows the bend. Release to finish the curve.","headingZh":"编辑曲线点","headingEn":"Edit Curve Point"},{"page":"chapter-01/index.html","ordinal":117,"anchor":"search-entry-117","zh":"此工具作用于版片的边线，不能在版片内部直接拉出曲线。","en":"This tool works on the pattern edge; it does not draw a curve inside the piece.","headingZh":"编辑曲线点","headingEn":"Edit Curve Point"},{"page":"chapter-01/index.html","ordinal":120,"anchor":"search-entry-120","zh":"编辑圆弧","en":"Edit Curvature","headingZh":"编辑圆弧","headingEn":"Edit Curvature"},{"page":"chapter-01/index.html","ordinal":122,"anchor":"search-entry-122","zh":"Edit Curvature","en":"Edit Curvature","headingZh":"编辑圆弧","headingEn":"Edit Curvature"},{"page":"chapter-01/index.html","ordinal":123,"anchor":"search-entry-123","zh":"2D → 编辑 → 编辑圆弧","en":"2D → Edit → Edit Curvature","headingZh":"编辑圆弧","headingEn":"Edit Curvature"},{"page":"chapter-01/index.html","ordinal":124,"anchor":"search-entry-124","zh":"直接拖动一段线或已有弧线，快速改变整段的弯曲程度。","en":"Drag a segment or an existing arc to change the bend of that whole section quickly.","headingZh":"编辑圆弧","headingEn":"Edit Curvature"},{"page":"chapter-01/index.html","ordinal":125,"anchor":"search-entry-125","zh":"长按编辑工具图标，在小菜单中选择「编辑圆弧」（C）。","en":"Press and hold the editing-tool icon, then choose Edit Curvature (C) from its flyout.","headingZh":"编辑圆弧","headingEn":"Edit Curvature"},{"page":"chapter-01/index.html","ordinal":126,"anchor":"search-entry-126","zh":"将鼠标放在线段或弧线上，按住左键向内或向外拖动；观察轮廓变化，松开鼠标完成调整。","en":"Place the pointer on a line or arc and drag inward or outward. Watch the outline change, then release to finish.","headingZh":"编辑圆弧","headingEn":"Edit Curvature"},{"page":"chapter-01/index.html","ordinal":127,"anchor":"search-entry-127","zh":"视频先把右侧边线拉成弧线，再调整顶部已有的弧线。","en":"The video first bends the right edge, then adjusts the existing arc at the top.","headingZh":"编辑圆弧","headingEn":"Edit Curvature"},{"page":"chapter-01/index.html","ordinal":131,"anchor":"search-entry-131","zh":"加点／分线","en":"Add Point / Split Line","headingZh":"加点／分线","headingEn":"Add Point / Split Line"},{"page":"chapter-01/index.html","ordinal":133,"anchor":"search-entry-133","zh":"Add Point / Split Line","en":"Add Point / Split Line","headingZh":"加点／分线","headingEn":"Add Point / Split Line"},{"page":"chapter-01/index.html","ordinal":134,"anchor":"search-entry-134","zh":"2D → 编辑 → 加点／分线","en":"2D → Edit → Add Point / Split Line","headingZh":"加点／分线","headingEn":"Add Point / Split Line"},{"page":"chapter-01/index.html","ordinal":135,"anchor":"search-entry-135","zh":"在版片边线上添加新点，把原线段分成更短的段，方便后续局部编辑。","en":"Add a new point to a pattern edge, dividing the original segment into shorter sections for later editing.","headingZh":"加点／分线","headingEn":"Add Point / Split Line"},{"page":"chapter-01/index.html","ordinal":136,"anchor":"search-entry-136","zh":"长按编辑工具图标，在小菜单中选择「加点／分线」（X）。","en":"Press and hold the editing-tool icon, then choose Add Point / Split Line (X) from its flyout.","headingZh":"加点／分线","headingEn":"Add Point / Split Line"},{"page":"chapter-01/index.html","ordinal":137,"anchor":"search-entry-137","zh":"在需要加点的直线或曲线上单击。新点会出现在点击处；视频中沿右侧边线连续添加了几个点。","en":"Click a straight or curved edge where you want a point. A new point appears there; the video adds several along the right edge.","headingZh":"加点／分线","headingEn":"Add Point / Split Line"},{"page":"chapter-01/index.html","ordinal":138,"anchor":"search-entry-138","zh":"加点会分割边线，不会把整块版片切成两块。","en":"Adding points divides the edge, not the pattern piece itself.","headingZh":"加点／分线","headingEn":"Add Point / Split Line"},{"page":"chapter-01/index.html","ordinal":141,"anchor":"search-entry-141","zh":"删除板片","en":"Delete a Pattern","headingZh":"删除板片","headingEn":"Delete a Pattern"},{"page":"chapter-01/index.html","ordinal":143,"anchor":"search-entry-143","zh":"Delete a Pattern","en":"Delete a Pattern","headingZh":"删除板片","headingEn":"Delete a Pattern"},{"page":"chapter-01/index.html","ordinal":144,"anchor":"search-entry-144","zh":"2D 窗口 → 选中版片 → Delete","en":"2D window → Select pattern → Delete","headingZh":"删除板片","headingEn":"Delete a Pattern"},{"page":"chapter-01/index.html","ordinal":145,"anchor":"search-entry-145","zh":"删除不需要的整块版片。先确认整片已被选中，再按键盘上的 Delete 键。","en":"Remove an unwanted pattern piece. Select the whole piece first, then press Delete on the keyboard.","headingZh":"删除板片","headingEn":"Delete a Pattern"},{"page":"chapter-01/index.html","ordinal":146,"anchor":"search-entry-146","zh":"使用「调整板片」（A），点击版片内部；看到蓝色轮廓和选框，表示整片已选中。","en":"Use Transform Pattern (A) and click inside the piece. A blue outline and bounding box show that the whole pattern is selected.","headingZh":"删除板片","headingEn":"Delete a Pattern"},{"page":"chapter-01/index.html","ordinal":147,"anchor":"search-entry-147","zh":"按 Delete。版片从 2D 窗口消失；如果误删，可立即按 Ctrl+Z 撤销。","en":"Press Delete. The pattern disappears from the 2D window. If it was a mistake, press Ctrl+Z to undo.","headingZh":"删除板片","headingEn":"Delete a Pattern"},{"page":"chapter-01/index.html","ordinal":148,"anchor":"search-entry-148","zh":"视频中的按键写作 Delete，常缩写为 Del。","en":"The key is spelled Delete and is often abbreviated Del.","headingZh":"删除板片","headingEn":"Delete a Pattern"},{"page":"chapter-01/index.html","ordinal":151,"anchor":"search-entry-151","zh":"创建矩形版片","en":"Create a Rectangle Pattern","headingZh":"创建矩形版片","headingEn":"Create a Rectangle Pattern"},{"page":"chapter-01/index.html","ordinal":153,"anchor":"search-entry-153","zh":"Rectangle","en":"Rectangle","headingZh":"创建矩形版片","headingEn":"Create a Rectangle Pattern"},{"page":"chapter-01/index.html","ordinal":154,"anchor":"search-entry-154","zh":"2D → 图形工具组 → 矩形","en":"2D → Shape tools → Rectangle","headingZh":"创建矩形版片","headingEn":"Create a Rectangle Pattern"},{"page":"chapter-01/index.html","ordinal":155,"anchor":"search-entry-155","zh":"从图形工具组选择「矩形」，在二维工作区画出一块矩形版片。","en":"Choose Rectangle from the shape-tool group and draw a rectangular pattern in the 2D workspace.","headingZh":"创建矩形版片","headingEn":"Create a Rectangle Pattern"},{"page":"chapter-01/index.html","ordinal":156,"anchor":"search-entry-156","zh":"长按 2D 窗口右侧的图形工具图标，在展开的小菜单中选择「矩形」（S）；也可以直接按 S。","en":"Press and hold the shape-tool icon on the right of the 2D window, then choose Rectangle (S) from the flyout. You can also press S.","headingZh":"创建矩形版片","headingEn":"Create a Rectangle Pattern"},{"page":"chapter-01/index.html","ordinal":157,"anchor":"search-entry-157","zh":"在工作区确定第一个角，向对角方向移动鼠标并完成绘制；白色矩形和四个角点出现后，版片就创建好了。","en":"Choose the first corner in the workspace, move toward the opposite corner, and complete the shape. The white rectangle and its four corner points show that the pattern has been created.","headingZh":"创建矩形版片","headingEn":"Create a Rectangle Pattern"},{"page":"chapter-01/index.html","ordinal":158,"anchor":"search-entry-158","zh":"图形工具组还包括多边形、圆形等工具；右下角的小三角表示可以长按展开。","en":"The same tool group also includes Polygon and Ellipse. The small triangle means you can press and hold to open the group.","headingZh":"创建矩形版片","headingEn":"Create a Rectangle Pattern"},{"page":"chapter-01/index.html","ordinal":162,"anchor":"search-entry-162","zh":"多边形","en":"Polygon","headingZh":"多边形","headingEn":"Polygon"},{"page":"chapter-01/index.html","ordinal":163,"anchor":"search-entry-163","zh":"Polygon","en":"Polygon","headingZh":"多边形","headingEn":"Polygon"},{"page":"chapter-01/index.html","ordinal":164,"anchor":"search-entry-164","zh":"2D → 生成 → 多边形","en":"2D → Create → Polygon","headingZh":"多边形","headingEn":"Polygon"},{"page":"chapter-01/index.html","ordinal":165,"anchor":"search-entry-165","zh":"逐点绘制自由轮廓的版片。","en":"Build a custom pattern outline point by point.","headingZh":"多边形","headingEn":"Polygon"},{"page":"chapter-01/index.html","ordinal":166,"anchor":"search-entry-166","zh":"按 H，在二维窗口依次单击各个转角。","en":"Press H and click each corner in the 2D window.","headingZh":"多边形","headingEn":"Polygon"},{"page":"chapter-01/index.html","ordinal":167,"anchor":"search-entry-167","zh":"最后单击起点，闭合轮廓并生成版片。","en":"Click the starting point again to close the pattern.","headingZh":"多边形","headingEn":"Polygon"},{"page":"chapter-01/index.html","ordinal":168,"anchor":"search-entry-168","zh":"先练习四边形；没有闭合的轮廓还不是完成的版片。","en":"Start with four corners and make sure the outline is closed.","headingZh":"多边形","headingEn":"Polygon"},{"page":"chapter-01/index.html","ordinal":172,"anchor":"search-entry-172","zh":"圆形","en":"Ellipse","headingZh":"圆形","headingEn":"Ellipse"},{"page":"chapter-01/index.html","ordinal":173,"anchor":"search-entry-173","zh":"Ellipse","en":"Ellipse","headingZh":"圆形","headingEn":"Ellipse"},{"page":"chapter-01/index.html","ordinal":174,"anchor":"search-entry-174","zh":"2D → 生成 → 圆形","en":"2D → Create → Ellipse","headingZh":"圆形","headingEn":"Ellipse"},{"page":"chapter-01/index.html","ordinal":175,"anchor":"search-entry-175","zh":"创建椭圆或圆形版片。此中文版本菜单显示「圆形」。","en":"Create ellipses or circles. This Chinese interface labels the tool 圆形.","headingZh":"圆形","headingEn":"Ellipse"},{"page":"chapter-01/index.html","ordinal":176,"anchor":"search-entry-176","zh":"按 E，在二维窗口按住左键拖动。","en":"Press E and click-drag in the 2D window.","headingZh":"圆形","headingEn":"Ellipse"},{"page":"chapter-01/index.html","ordinal":177,"anchor":"search-entry-177","zh":"松开完成椭圆；按住 Shift 拖动可创建正圆。","en":"Release for an ellipse; hold Shift while dragging for a circle.","headingZh":"圆形","headingEn":"Ellipse"},{"page":"chapter-01/index.html","ordinal":178,"anchor":"search-entry-178","zh":"单击空白处可以打开尺寸输入窗口。","en":"Click once in empty space to open the size dialog.","headingZh":"圆形","headingEn":"Ellipse"},{"page":"chapter-01/index.html","ordinal":180,"anchor":"search-entry-180","zh":"内部形状：绘制、切断与镂空","en":"Internal Shapes: Draw, Cut & Make a Hole","headingZh":"内部形状：绘制、切断与镂空","headingEn":"Internal Shapes: Draw, Cut & Make a Hole"},{"page":"chapter-01/index.html","ordinal":181,"anchor":"search-entry-181","zh":"Internal Shapes","en":"Internal Shapes","headingZh":"内部形状：绘制、切断与镂空","headingEn":"Internal Shapes: Draw, Cut & Make a Hole"},{"page":"chapter-01/index.html","ordinal":182,"anchor":"search-entry-182","zh":"2D → 右侧内部形状工具组","en":"2D → Internal-shape tool group on the right","headingZh":"内部形状：绘制、切断与镂空","headingEn":"Internal Shapes: Draw, Cut & Make a Hole"},{"page":"chapter-01/index.html","ordinal":183,"anchor":"search-entry-183","zh":"长按这个图标可展开内部形状工具组。下面以「内部矩形」为例；同组还有「内部多边形／线」（G）等工具。","en":"Press and hold this icon to open the internal-shape tools. The lesson uses Internal Rectangle; the group also includes Internal Polygon / Line (G).","headingZh":"内部形状：绘制、切断与镂空","headingEn":"Internal Shapes: Draw, Cut & Make a Hole"},{"page":"chapter-01/index.html","ordinal":184,"anchor":"search-entry-184","zh":"内部形状只能画在已有版片内。未选中时，内部线显示为红色；选中后会高亮，也可以用编辑工具调整点和线。单纯画出内部形状，并不会立刻切开版片。","en":"Internal shapes can only be drawn inside an existing pattern. Their lines appear red when unselected and highlight when selected. You can edit their points and edges with an editing tool. Drawing an internal shape alone does not cut the pattern.","headingZh":"内部形状：绘制、切断与镂空","headingEn":"Internal Shapes: Draw, Cut & Make a Hole"},{"page":"chapter-01/index.html","ordinal":185,"anchor":"search-entry-185","zh":"添加并编辑内部形状","en":"Draw and edit an internal shape","headingZh":"添加并编辑内部形状","headingEn":"Draw and edit an internal shape"},{"page":"chapter-01/index.html","ordinal":186,"anchor":"search-entry-186","zh":"在版片内部选择「内部矩形」，确定两个对角位置，画出闭合轮廓。","en":"Choose Internal Rectangle and set two opposite corners inside the pattern to draw a closed outline.","headingZh":"添加并编辑内部形状","headingEn":"Draw and edit an internal shape"},{"page":"chapter-01/index.html","ordinal":187,"anchor":"search-entry-187","zh":"切换到编辑工具，选中内部线的点或边并拖动，调整形状。","en":"Switch to an editing tool, then select and drag a point or edge to reshape the outline.","headingZh":"添加并编辑内部形状","headingEn":"Draw and edit an internal shape"},{"page":"chapter-01/index.html","ordinal":188,"anchor":"search-entry-188","zh":"切断：得到两块裁片","en":"Cut: create two pattern pieces","headingZh":"切断：得到两块裁片","headingEn":"Cut: create two pattern pieces"},{"page":"chapter-01/index.html","ordinal":189,"anchor":"search-entry-189","zh":"选中闭合的内部形状，右键选择「切断」。","en":"Select the closed internal shape, right-click, and choose Cut.","headingZh":"切断：得到两块裁片","headingEn":"Cut: create two pattern pieces"},{"page":"chapter-01/index.html","ordinal":190,"anchor":"search-entry-190","zh":"CLO 沿轮廓把原版片分成外侧和内侧裁片；两块都可以单独移动。","en":"CLO splits the original pattern into outer and inner pieces along the outline. You can move each piece separately.","headingZh":"切断：得到两块裁片","headingEn":"Cut: create two pattern pieces"},{"page":"chapter-01/index.html","ordinal":191,"anchor":"search-entry-191","zh":"转化为洞：留下镂空","en":"Convert to Hole: make a cutout","headingZh":"转化为洞：留下镂空","headingEn":"Convert to Hole: make a cutout"},{"page":"chapter-01/index.html","ordinal":192,"anchor":"search-entry-192","zh":"选中闭合的内部形状，右键选择「转化为洞」。","en":"Select the closed internal shape, right-click, and choose Convert to Hole.","headingZh":"转化为洞：留下镂空","headingEn":"Convert to Hole: make a cutout"},{"page":"chapter-01/index.html","ordinal":193,"anchor":"search-entry-193","zh":"内部区域变成透明开口，原版片保留外框；不会另外生成内侧裁片。","en":"The enclosed area becomes a transparent opening. The outer pattern remains, and no separate inner piece is created.","headingZh":"转化为洞：留下镂空","headingEn":"Convert to Hole: make a cutout"},{"page":"chapter-01/index.html","ordinal":194,"anchor":"search-entry-194","zh":"记住区别：切断会得到内外两块可分别移动的裁片；转化为洞只在原版片上留下开口。","en":"Remember: Cut creates inner and outer pieces that can move separately; Convert to Hole leaves an opening in the original pattern.","headingZh":"转化为洞：留下镂空","headingEn":"Convert to Hole: make a cutout"},{"page":"chapter-01/index.html","ordinal":195,"anchor":"search-entry-195","zh":"三维操作与模拟","en":"3D controls & simulation","headingZh":"三维操作与模拟","headingEn":"3D controls & simulation"},{"page":"chapter-01/index.html","ordinal":196,"anchor":"search-entry-196","zh":"先学习用 Gizmo 调整版片，再从模块库添加服装版片、利用模特的安排点快速放置；最后再认识模拟功能。","en":"First use the Gizmo to adjust patterns. Then add ready-made pieces from the Module Library and place them with the avatar’s arrangement points before learning Simulation.","headingZh":"三维操作与模拟","headingEn":"3D controls & simulation"},{"page":"chapter-01/index.html","ordinal":197,"anchor":"search-entry-197","zh":"Gizmo · 三维操纵器","en":"Gizmo · 3D Transform Controls","headingZh":"Gizmo · 三维操纵器","headingEn":"Gizmo · 3D Transform Controls"},{"page":"chapter-01/index.html","ordinal":198,"anchor":"search-entry-198","zh":"在 2D 工作区选中一块版片，3D 窗口中的同一块版片也会变成黄色高亮，并出现 Gizmo。它是调整版片位置与方向的控制器。","en":"Select a pattern piece in the 2D workspace. The same piece highlights yellow in the 3D window, and the Gizmo appears. Use it to adjust the piece's position and orientation.","headingZh":"Gizmo · 三维操纵器","headingEn":"Gizmo · 3D Transform Controls"},{"page":"chapter-01/index.html","ordinal":200,"anchor":"search-entry-200","zh":"黄色高亮＝已选中","en":"Yellow highlight = selected","headingZh":"Gizmo · 三维操纵器","headingEn":"Gizmo · 3D Transform Controls"},{"page":"chapter-01/index.html","ordinal":201,"anchor":"search-entry-201","zh":"2D 和 3D 中高亮的是同一块版片；移动或旋转的是版片，不是相机。","en":"The highlighted shape is the same pattern in both windows. The Gizmo transforms the pattern, not the camera.","headingZh":"Gizmo · 三维操纵器","headingEn":"Gizmo · 3D Transform Controls"},{"page":"chapter-01/index.html","ordinal":202,"anchor":"search-entry-202","zh":"直线箭头＝移动","en":"Straight arrows = move","headingZh":"Gizmo · 三维操纵器","headingEn":"Gizmo · 3D Transform Controls"},{"page":"chapter-01/index.html","ordinal":203,"anchor":"search-entry-203","zh":"按住箭头拖动，沿对应方向移动版片。","en":"Drag an arrow to move the piece along that direction.","headingZh":"Gizmo · 三维操纵器","headingEn":"Gizmo · 3D Transform Controls"},{"page":"chapter-01/index.html","ordinal":204,"anchor":"search-entry-204","zh":"彩色圆环＝旋转","en":"Colored rings = rotate","headingZh":"Gizmo · 三维操纵器","headingEn":"Gizmo · 3D Transform Controls"},{"page":"chapter-01/index.html","ordinal":205,"anchor":"search-entry-205","zh":"按住圆环拖动，让版片绕对应轴转动。","en":"Drag a ring to rotate the piece around its corresponding axis.","headingZh":"Gizmo · 三维操纵器","headingEn":"Gizmo · 3D Transform Controls"},{"page":"chapter-01/index.html","ordinal":206,"anchor":"search-entry-206","zh":"先辨认坐标模式","en":"Check the coordinate mode","headingZh":"Gizmo · 三维操纵器","headingEn":"Gizmo · 3D Transform Controls"},{"page":"chapter-01/index.html","ordinal":207,"anchor":"search-entry-207","zh":"如果使用「屏幕坐标／视角」模式，Gizmo 的轴会跟随当前相机视角；它不是固定的世界坐标。斜着看时，屏幕上看似向旁边拖动，换个角度可能发现版片也有前后偏移。调整后从其他视角复查；需要固定空间方向时，可切换到「世界坐标」模式。","en":"In Screen Coordinate mode, the Gizmo axes follow the camera view rather than fixed world axes. From an oblique angle, a drag that looks sideways on screen can leave the piece offset in depth. Check from another view afterward, or switch to World Coordinate mode when you need fixed spatial directions.","headingZh":"Gizmo · 三维操纵器","headingEn":"Gizmo · 3D Transform Controls"},{"page":"chapter-01/index.html","ordinal":208,"anchor":"search-entry-208","zh":"选中版片，使用 Gizmo 移动与旋转","en":"Select, move, and rotate with the Gizmo","headingZh":"选中版片，使用 Gizmo 移动与旋转","headingEn":"Select, move, and rotate with the Gizmo"},{"page":"chapter-01/index.html","ordinal":209,"anchor":"search-entry-209","zh":"观察右侧 2D 版片被选中后，左侧 3D 版片同步变黄。拖动直线箭头可移动，拖动圆环可旋转。","en":"Watch the 2D selection highlight the same piece in 3D. Drag a straight arrow to move it and a ring to rotate it.","headingZh":"选中版片，使用 Gizmo 移动与旋转","headingEn":"Select, move, and rotate with the Gizmo"},{"page":"chapter-01/index.html","ordinal":210,"anchor":"search-entry-210","zh":"换个视角，检查版片位置","en":"Change view and check placement","headingZh":"换个视角，检查版片位置","headingEn":"Change view and check placement"},{"page":"chapter-01/index.html","ordinal":211,"anchor":"search-entry-211","zh":"先调整观察角度，再从侧面或上方检查版片与模特的距离；改变视角本身不会移动版片。","en":"Adjust the camera angle, then inspect the piece's distance from the avatar from the side or above. Changing the view alone does not move the pattern.","headingZh":"换个视角，检查版片位置","headingEn":"Change view and check placement"},{"page":"chapter-01/index.html","ordinal":212,"anchor":"search-entry-212","zh":"用固定视角更精确地调整","en":"Use fixed views for precise placement","headingZh":"换个视角，检查版片位置","headingEn":"Change view and check placement"},{"page":"chapter-01/index.html","ordinal":213,"anchor":"search-entry-213","zh":"在 3D 窗口按数字键切换视角，再观察并调整版片：","en":"With the 3D window active, press a number key to change views before checking and adjusting the piece:","headingZh":"换个视角，检查版片位置","headingEn":"Change view and check placement"},{"page":"chapter-01/index.html","ordinal":221,"anchor":"search-entry-221","zh":"模块库与安排点 · 快速放置版片","en":"Module Library & Arrangement Points","headingZh":"模块库与安排点 · 快速放置版片","headingEn":"Module Library & Arrangement Points"},{"page":"chapter-01/index.html","ordinal":222,"anchor":"search-entry-222","zh":"先从模块库取用现成服装版片，再显示模特身上的安排点，让版片快速到达合适的位置。","en":"Add ready-made pattern pieces from the Module Library, then use the avatar's arrangement points to place them quickly.","headingZh":"模块库与安排点 · 快速放置版片","headingEn":"Module Library & Arrangement Points"},{"page":"chapter-01/index.html","ordinal":223,"anchor":"search-entry-223","zh":"从模块库添加版片","en":"Add pattern pieces from the Module Library","headingZh":"从模块库添加版片","headingEn":"Add pattern pieces from the Module Library"},{"page":"chapter-01/index.html","ordinal":224,"anchor":"search-entry-224","zh":"点击工作区左侧的「模块库」，打开现成的服装模板。录屏里先进入上衣分类，再打开一组版片；你电脑中的分类和文件可能不同。","en":"Open the Module Library on the left. In the recording, the instructor opens a top template and its pattern pieces; folders and files may differ on your computer.","headingZh":"从模块库添加版片","headingEn":"Add pattern pieces from the Module Library"},{"page":"chapter-01/index.html","ordinal":225,"anchor":"search-entry-225","zh":"双击需要的版片缩略图，把版片加入当前项目。观察 2D 窗口出现版片，3D 窗口也同步出现对应的版片。","en":"Double-click a pattern thumbnail to add it to the current project. The piece appears in both the 2D and 3D windows.","headingZh":"从模块库添加版片","headingEn":"Add pattern pieces from the Module Library"},{"page":"chapter-01/index.html","ordinal":226,"anchor":"search-entry-226","zh":"添加后选中版片，按上一节的方法使用 Gizmo 移动、旋转，并换个视角检查它与模特的距离。","en":"Select the added piece, use the Gizmo from the previous lesson to move or rotate it, and check its distance from the avatar from another view.","headingZh":"从模块库添加版片","headingEn":"Add pattern pieces from the Module Library"},{"page":"chapter-01/index.html","ordinal":227,"anchor":"search-entry-227","zh":"显示安排点，让版片快速就位","en":"Show arrangement points and place a piece","headingZh":"显示安排点，让版片快速就位","headingEn":"Show arrangement points and place a piece"},{"page":"chapter-01/index.html","ordinal":228,"anchor":"search-entry-228","zh":"点击模块库面板右侧的小箭头，将面板收起，留出更多 3D 操作空间。","en":"Click the small arrow at the right edge of the Module Library panel to collapse it and make more room in the 3D window.","headingZh":"显示安排点，让版片快速就位","headingEn":"Show arrangement points and place a piece"},{"page":"chapter-01/index.html","ordinal":229,"anchor":"search-entry-229","zh":"在模特左侧工具栏，长按「虚拟模特信息显示」图标，打开小菜单，选择「显示安排点」（快捷键 Shift+F）。模特周围会出现蓝色安排点。","en":"Long-press the Avatar Information Display icon beside the avatar. In its menu, choose Show Arrangement Points (Shift+F). Blue points appear around the avatar.","headingZh":"显示安排点，让版片快速就位","headingEn":"Show arrangement points and place a piece"},{"page":"chapter-01/index.html","ordinal":230,"anchor":"search-entry-230","zh":"在 2D 或 3D 窗口选中一块版片，再点击模特身上合适的蓝色点。版片会自动移动到该安排位置；随后从正面和侧面检查，并按需用 Gizmo 微调。","en":"Select a piece in either the 2D or 3D window, then click a suitable blue point on the avatar. The piece snaps to that arrangement location. Check it from front and side views and refine with the Gizmo if needed.","headingZh":"显示安排点，让版片快速就位","headingEn":"Show arrangement points and place a piece"},{"page":"chapter-01/index.html","ordinal":232,"anchor":"search-entry-232","zh":"模拟 · 让版片成为服装","en":"Simulation · Turn patterns into a garment","headingZh":"模拟 · 让版片成为服装","headingEn":"Simulation · Turn patterns into a garment"},{"page":"chapter-01/index.html","ordinal":233,"anchor":"search-entry-233","zh":"3D 窗口中，版片之间的彩色线条表示缝纫关系：两块版片的边缘已设为相互连接。启动模拟后，CLO 会计算布料在重力和碰撞下的形状。","en":"Colored lines between pieces in the 3D window show sewing relationships between their edges. When Simulation runs, CLO calculates the fabric's response to gravity and collisions.","headingZh":"模拟 · 让版片成为服装","headingEn":"Simulation · Turn patterns into a garment"},{"page":"chapter-01/index.html","ordinal":234,"anchor":"search-entry-234","zh":"模拟开启时，左侧箭头变蓝","en":"The left arrow turns blue while Simulation runs","headingZh":"模拟 · 让版片成为服装","headingEn":"Simulation · Turn patterns into a garment"},{"page":"chapter-01/index.html","ordinal":235,"anchor":"search-entry-235","zh":"空格键：启动与暂停模拟","en":"Spacebar: start and pause Simulation","headingZh":"空格键：启动与暂停模拟","headingEn":"Spacebar: start and pause Simulation"},{"page":"chapter-01/index.html","ordinal":236,"anchor":"search-entry-236","zh":"按空格键启动模拟，左侧工具栏的模拟箭头会变为蓝色。观察原本分开的版片如何根据缝纫线连接、落到模特身上，逐渐形成服装的垂坠。再次按空格键可暂停模拟。","en":"Press Space to start Simulation. The arrow on the left toolbar turns blue. Watch the separate pieces connect along their sewing lines, settle onto the avatar, and drape as a garment. Press Space again to pause.","headingZh":"空格键：启动与暂停模拟","headingEn":"Spacebar: start and pause Simulation"},{"page":"chapter-01/index.html","ordinal":237,"anchor":"search-entry-237","zh":"拖拽布料，观察实时变化","en":"Drag the fabric and observe its response","headingZh":"拖拽布料，观察实时变化","headingEn":"Drag the fabric and observe its response"},{"page":"chapter-01/index.html","ordinal":238,"anchor":"search-entry-238","zh":"模拟运行时，在 3D 服装上按住鼠标左键并拖动。布料会被拉起或推开，周围的褶皱随之变化；松开鼠标后，布料继续受重力影响重新垂落。","en":"While Simulation is running, hold the left mouse button on the 3D garment and drag. The fabric lifts or shifts and nearby folds change; after release, gravity makes it settle again.","headingZh":"拖拽布料，观察实时变化","headingEn":"Drag the fabric and observe its response"},{"page":"chapter-01/index.html","ordinal":239,"anchor":"search-entry-239","zh":"衣片掉落后，先暂停","en":"If pieces fall away, pause first","headingZh":"衣片掉落后，先暂停","headingEn":"If pieces fall away, pause first"},{"page":"chapter-01/index.html","ordinal":240,"anchor":"search-entry-240","zh":"服装没有放在模特身上时，模拟中的重力会让它下坠。虽然可以用鼠标抓起，版片往往会皱缩，难以靠拖拽恢复平整。先按空格键暂停模拟，再重置版片。","en":"If the garment is away from the avatar, gravity makes it fall during Simulation. You can lift it with the mouse, but it may remain crumpled. Press Space to pause, then reset the pieces.","headingZh":"衣片掉落后，先暂停","headingEn":"If pieces fall away, pause first"},{"page":"chapter-01/index.html","ordinal":241,"anchor":"search-entry-241","zh":"重置 3D 版片，恢复平展","en":"Reset 3D Pattern to flatten the pieces","headingZh":"重置 3D 版片，恢复平展","headingEn":"Reset 3D Pattern to flatten the pieces"},{"page":"chapter-01/index.html","ordinal":242,"anchor":"search-entry-242","zh":"先选中要处理的版片。任何编辑都应先明确目标；在 2D 工作区框选多块版片通常更方便。","en":"First select the pieces you want to change. Editing requires a clear target; box-selecting several pieces is often easier in the 2D window.","headingZh":"重置 3D 版片，恢复平展","headingEn":"Reset 3D Pattern to flatten the pieces"},{"page":"chapter-01/index.html","ordinal":243,"anchor":"search-entry-243","zh":"鼠标移回 3D 窗口，在选中的版片上右键，选择「重置 3D 版片」。","en":"Move back to the 3D window, right-click the selected piece, and choose Reset 3D Pattern.","headingZh":"重置 3D 版片，恢复平展","headingEn":"Reset 3D Pattern to flatten the pieces"},{"page":"chapter-01/index.html","ordinal":244,"anchor":"search-entry-244","zh":"版片会恢复平展，但不一定回到原来的位置；必要时再用 Gizmo 或安排点重新放置。","en":"The pieces flatten, but may not return to their former locations. Use the Gizmo or arrangement points to position them again if needed.","headingZh":"重置 3D 版片，恢复平展","headingEn":"Reset 3D Pattern to flatten the pieces"},{"page":"chapter-01/index.html","ordinal":245,"anchor":"search-entry-245","zh":"3D 笔 · 在模特身上绘制版片","en":"3D Pen · Draw patterns on the avatar","headingZh":"3D 笔 · 在模特身上绘制版片","headingEn":"3D Pen · Draw patterns on the avatar"},{"page":"chapter-01/index.html","ordinal":246,"anchor":"search-entry-246","zh":"先在模特表面画出闭合轮廓，再将选中的区域展平为二维版片。","en":"Draw a closed outline on the avatar, then flatten the selected region into a 2D pattern.","headingZh":"3D 笔 · 在模特身上绘制版片","headingEn":"3D Pen · Draw patterns on the avatar"},{"page":"chapter-01/index.html","ordinal":247,"anchor":"search-entry-247","zh":"沿身体逐点绘制闭合轮廓","en":"Draw and close an outline on the body","headingZh":"沿身体逐点绘制闭合轮廓","headingEn":"Draw and close an outline on the body"},{"page":"chapter-01/index.html","ordinal":248,"anchor":"search-entry-248","zh":"在模特左侧工具栏长按图标，选择「3D 笔（虚拟模特）」。在 3D 窗口点击起点，再沿要制作的版片轮廓逐点点击；最后回到起点，让首尾相接，形成封闭区域。","en":"Long-press the icon beside the avatar and choose 3D Pen (Avatar). Click a starting point in the 3D window, then click successive points around the desired pattern outline. Finish by clicking the start point to close the shape.","headingZh":"沿身体逐点绘制闭合轮廓","headingEn":"Draw and close an outline on the body"},{"page":"chapter-01/index.html","ordinal":250,"anchor":"search-entry-250","zh":"展平为板片，同步到 2D 工作区","en":"Flatten the shape into a 2D pattern","headingZh":"展平为板片，同步到 2D 工作区","headingEn":"Flatten the shape into a 2D pattern"},{"page":"chapter-01/index.html","ordinal":251,"anchor":"search-entry-251","zh":"在同一工具菜单选择「展平为板片」，把鼠标移到刚画好的区域。闭合有效时，悬停的区域会变蓝；如果没有响应，先检查轮廓是否首尾相接。","en":"Choose Flatten as Pattern in the same tool menu and hover over the drawn region. A valid closed region turns blue. If nothing happens, check that the outline meets its starting point.","headingZh":"展平为板片，同步到 2D 工作区","headingEn":"Flatten the shape into a 2D pattern"},{"page":"chapter-01/index.html","ordinal":252,"anchor":"search-entry-252","zh":"点击蓝色区域，它会变为黄色，表示已选中；需要时可继续选择其他闭合区域。","en":"Click the blue region. It turns yellow to show it is selected. You may select more closed regions if needed.","headingZh":"展平为板片，同步到 2D 工作区","headingEn":"Flatten the shape into a 2D pattern"},{"page":"chapter-01/index.html","ordinal":253,"anchor":"search-entry-253","zh":"按 Enter 结束选择并展平。新板片会同时出现在 3D 模特上和 2D 工作区。","en":"Press Enter to finish selecting and flatten. The new pattern appears on the 3D avatar and in the 2D workspace.","headingZh":"展平为板片，同步到 2D 工作区","headingEn":"Flatten the shape into a 2D pattern"},{"page":"chapter-01/index.html","ordinal":255,"anchor":"search-entry-255","zh":"编辑 3D 笔 · 调整模特身上的轮廓","en":"Edit 3D Pen · Refine the outline on the avatar","headingZh":"编辑 3D 笔 · 调整模特身上的轮廓","headingEn":"Edit 3D Pen · Refine the outline on the avatar"},{"page":"chapter-01/index.html","ordinal":256,"anchor":"search-entry-256","zh":"选择左侧工具栏的「编辑 3D 笔（虚拟模特）」。在 3D 窗口点击已绘制的点或线，选中后拖动，可调整轮廓的位置和形状。录屏中依次移动了中线上的点和右侧边线，选中的线会高亮，长度数值也会随调整变化。","en":"Choose Edit 3D Pen (Avatar) on the left toolbar. Click a point or line in the 3D window and drag it to refine the outline. In the recording, points on the center edge and the right side are moved; selected lines highlight and their displayed lengths change.","headingZh":"编辑 3D 笔 · 调整模特身上的轮廓","headingEn":"Edit 3D Pen · Refine the outline on the avatar"},{"page":"chapter-01/index.html","ordinal":257,"anchor":"search-entry-257","zh":"不需要的点或线，可先选中再按 Delete 删除。删除后检查轮廓是否仍然闭合，避免后续无法「展平为板片」。","en":"To remove a point or line, select it and press Delete. Check that the outline remains closed afterward so Flatten as Pattern can still recognize the region.","headingZh":"编辑 3D 笔 · 调整模特身上的轮廓","headingEn":"Edit 3D Pen · Refine the outline on the avatar"},{"page":"chapter-01/index.html","ordinal":258,"anchor":"search-entry-258","zh":"编辑 3D 笔工具","en":"Edit 3D Pen tool","headingZh":"编辑 3D 笔 · 调整模特身上的轮廓","headingEn":"Edit 3D Pen · Refine the outline on the avatar"},{"page":"chapter-01/index.html","ordinal":259,"anchor":"search-entry-259","zh":"建立缝纫关系","en":"Create sewing relationships","headingZh":"建立缝纫关系","headingEn":"Create sewing relationships"},{"page":"chapter-01/index.html","ordinal":260,"anchor":"search-entry-260","zh":"先在 2D 工作区查看或删除缝线，再学习线缝纫与自由缝纫。检查缝线方向后，还可以用对称展开编辑半片服装，让两侧版片与缝线同步。","en":"Inspect or delete seams in 2D, then learn Segment and Free Sewing. After checking seam direction, use symmetric editing to mirror a half pattern and its sewing lines.","headingZh":"建立缝纫关系","headingEn":"Create sewing relationships"},{"page":"chapter-01/index.html","ordinal":261,"anchor":"search-entry-261","zh":"编辑缝纫线 · 查看与删除","en":"Edit Sewing · Inspect and delete seams","headingZh":"编辑缝纫线 · 查看与删除","headingEn":"Edit Sewing · Inspect and delete seams"},{"page":"chapter-01/index.html","ordinal":262,"anchor":"search-entry-262","zh":"3D 窗口里，版片之间的彩色线条表示两条边已建立缝纫关系。要查看或编辑这些缝线，请回到 2D 工作区并选择「编辑缝纫线」工具。","en":"Colored lines between pieces in the 3D window indicate that their edges are sewn together. To inspect or edit those seams, use Edit Sewing in the 2D workspace.","headingZh":"编辑缝纫线 · 查看与删除","headingEn":"Edit Sewing · Inspect and delete seams"},{"page":"chapter-01/index.html","ordinal":263,"anchor":"search-entry-263","zh":"编辑缝纫线工具","en":"Edit Sewing tool","headingZh":"编辑缝纫线 · 查看与删除","headingEn":"Edit Sewing · Inspect and delete seams"},{"page":"chapter-01/index.html","ordinal":264,"anchor":"search-entry-264","zh":"显示并检查缝线","en":"Reveal and inspect the seams","headingZh":"显示并检查缝线","headingEn":"Reveal and inspect the seams"},{"page":"chapter-01/index.html","ordinal":265,"anchor":"search-entry-265","zh":"点击「编辑缝纫线」（快捷键 B）。2D 版片边缘的缝线会显示出来；选中一条缝线，可以对照 3D 窗口里的彩色连接线，找到它缝向哪一条边。","en":"Choose Edit Sewing (B). The seam lines appear along the 2D pattern edges. Select one and compare it with the colored connection in 3D to see which edges are paired.","headingZh":"显示并检查缝线","headingEn":"Reveal and inspect the seams"},{"page":"chapter-01/index.html","ordinal":266,"anchor":"search-entry-266","zh":"删除错误的缝线","en":"Delete an incorrect seam","headingZh":"删除错误的缝线","headingEn":"Delete an incorrect seam"},{"page":"chapter-01/index.html","ordinal":267,"anchor":"search-entry-267","zh":"保持「编辑缝纫线」工具，在 2D 工作区选中要删除的缝线，再按键盘 Delete（有些键盘标为 Del）。对应的缝纫关系会消失，便可重新连接正确的边。","en":"With Edit Sewing active, select the seam in the 2D workspace and press Delete (Del on some keyboards). The sewing relationship is removed so you can connect the correct edges again.","headingZh":"删除错误的缝线","headingEn":"Delete an incorrect seam"},{"page":"chapter-01/index.html","ordinal":268,"anchor":"search-entry-268","zh":"线缝纫 · 点击两条边完成连接","en":"Segment Sewing · Click two edges to connect them","headingZh":"线缝纫 · 点击两条边完成连接","headingEn":"Segment Sewing · Click two edges to connect them"},{"page":"chapter-01/index.html","ordinal":269,"anchor":"search-entry-269","zh":"选择「线缝纫」（快捷键 N），依次点击要连接的两条版片边线。缝线一端的短标记类似剪口，提示缝纫的起始端；两边的起止方向要对应。完成后到 3D 窗口查看彩色线条的走向。","en":"Choose Segment Sewing (N), then click the two pattern edges in sequence. A small notch-like mark indicates the starting end of a seam. Match the direction on both edges and inspect the colored connection lines in 3D.","headingZh":"线缝纫 · 点击两条边完成连接","headingEn":"Segment Sewing · Click two edges to connect them"},{"page":"chapter-01/index.html","ordinal":271,"anchor":"search-entry-271","zh":"正确示范：按顺序点击两条边","en":"Correct example: click the two edges in order","headingZh":"正确示范：按顺序点击两条边","headingEn":"Correct example: click the two edges in order"},{"page":"chapter-01/index.html","ordinal":272,"anchor":"search-entry-272","zh":"先点击第一条边，再点击对应的第二条边；留意起始端标记。2D 中确认缝线关系后，转到 3D 检查彩色线条是否顺畅，再启动模拟查看服装落下的效果。","en":"Click the first edge, then its matching second edge, paying attention to the start markers. Check the seam in 2D and the colored lines in 3D, then run Simulation to see the garment settle.","headingZh":"正确示范：按顺序点击两条边","headingEn":"Correct example: click the two edges in order"},{"page":"chapter-01/index.html","ordinal":273,"anchor":"search-entry-273","zh":"错误示范：缝线交叉","en":"Incorrect example: crossed seam lines","headingZh":"错误示范：缝线交叉","headingEn":"Incorrect example: crossed seam lines"},{"page":"chapter-01/index.html","ordinal":274,"anchor":"search-entry-274","zh":"如果两条边的起止方向接反，3D 窗口里的彩色连接线会交叉。本例中看到交叉线时，应先停下来检查缝线方向，不要直接进入模拟。","en":"If the start and end directions are reversed, the colored connection lines cross in the 3D window. In this example, stop and check the seam direction before simulating.","headingZh":"错误示范：缝线交叉","headingEn":"Incorrect example: crossed seam lines"},{"page":"chapter-01/index.html","ordinal":275,"anchor":"search-entry-275","zh":"错误模拟：版片扭曲怎么办？","en":"If the garment twists during Simulation","headingZh":"错误模拟：版片扭曲怎么办？","headingEn":"If the garment twists during Simulation"},{"page":"chapter-01/index.html","ordinal":276,"anchor":"search-entry-276","zh":"沿用刚才缝反的关系启动模拟，服装会被拉扯、扭曲。按空格键暂停，删除错误缝线；如果版片已经皱缩，先重置 3D 版片，再按正确方向重缝。","en":"Run Simulation with that reversed seam and the garment pulls and twists. Press Space to pause, delete the incorrect seam, and reset crumpled 3D pieces before sewing again in the correct direction.","headingZh":"错误模拟：版片扭曲怎么办？","headingEn":"If the garment twists during Simulation"},{"page":"chapter-01/index.html","ordinal":278,"anchor":"search-entry-278","zh":"自由缝纫 · 从点到点指定范围","en":"Free Sewing · Define a seam point by point","headingZh":"自由缝纫 · 从点到点指定范围","headingEn":"Free Sewing · Define a seam point by point"},{"page":"chapter-01/index.html","ordinal":279,"anchor":"search-entry-279","zh":"「线缝纫」是依次点击两条完整边线；这里使用截图中红框标出的「M:N 自由缝纫」，从边线上的一个点开始，再指定终点，可只缝其中一段。","en":"Segment Sewing connects two whole edges by clicking them. Here, choose the highlighted M:N Free Sewing option and define a seam from a start point to an end point along each edge.","headingZh":"自由缝纫 · 从点到点指定范围","headingEn":"Free Sewing · Define a seam point by point"},{"page":"chapter-01/index.html","ordinal":281,"anchor":"search-entry-281","zh":"先选起点，再选终点","en":"Choose a start point, then an end point","headingZh":"先选起点，再选终点","headingEn":"Choose a start point, then an end point"},{"page":"chapter-01/index.html","ordinal":282,"anchor":"search-entry-282","zh":"在第一块版片的边线上点击缝合起点，再点击终点，确定第一段缝纫范围。随后到另一块版片，按对应方向选择第二段的起点与终点。","en":"Click a start point and an end point on the first pattern edge to define the first sewing span. On the matching pattern, choose the second span's start and end in the corresponding direction.","headingZh":"先选起点，再选终点","headingEn":"Choose a start point, then an end point"},{"page":"chapter-01/index.html","ordinal":283,"anchor":"search-entry-283","zh":"终点可以在线段中间","en":"The end point can be anywhere on an edge","headingZh":"终点可以在线段中间","headingEn":"The end point can be anywhere on an edge"},{"page":"chapter-01/index.html","ordinal":284,"anchor":"search-entry-284","zh":"不必缝到整条边的末端；可在线段任意位置点击，作为缝合终点。选择第二段时，线上出现的蓝色小点是按第一段长度给出的参考终点，便于对齐两侧缝合范围。","en":"The seam need not reach the end of the whole edge. Click anywhere along it to place an end point. While defining the second span, a small blue point marks the end position matching the first span's length.","headingZh":"终点可以在线段中间","headingEn":"The end point can be anywhere on an edge"},{"page":"chapter-01/index.html","ordinal":285,"anchor":"search-entry-285","zh":"对称展开编辑（缝纫线）与解除联动","en":"Symmetric Pattern with Sewing · Unlinking","headingZh":"对称展开编辑（缝纫线）与解除联动","headingEn":"Symmetric Pattern with Sewing · Unlinking"},{"page":"chapter-01/index.html","ordinal":286,"anchor":"search-entry-286","zh":"制作左右对称的服装时，可以先画好前身或后身的一半，再让 CLO 镜像展开另一半。选择带「缝纫线」的对称展开方式，后续调整半片形状或添加缝线时，另一侧也会同步。","en":"For a symmetrical garment, draft one half of the front or back pattern first, then mirror it in CLO. With the sewing-aware symmetric edit command, changes to the shape or seams on one half update the other half too.","headingZh":"对称展开编辑（缝纫线）与解除联动","headingEn":"Symmetric Pattern with Sewing · Unlinking"},{"page":"chapter-01/index.html","ordinal":287,"anchor":"search-entry-287","zh":"只画半片，再对称展开","en":"Draft half, then expand symmetrically","headingZh":"只画半片，再对称展开","headingEn":"Draft half, then expand symmetrically"},{"page":"chapter-01/index.html","ordinal":288,"anchor":"search-entry-288","zh":"选择「编辑板片」工具，在 2D 工作区选中半片的中线。","en":"Choose Edit Pattern and select the half-pattern's center line in the 2D workspace.","headingZh":"只画半片，再对称展开","headingEn":"Draft half, then expand symmetrically"},{"page":"chapter-01/index.html","ordinal":289,"anchor":"search-entry-289","zh":"右键选择「对称展开编辑（缝纫线）」。版片沿中线镜像展开，不必手动画另一半。","en":"Right-click and choose Symmetric Pattern with Sewing. CLO mirrors the piece across the center line; there is no need to draw the other half manually.","headingZh":"只画半片，再对称展开","headingEn":"Draft half, then expand symmetrically"},{"page":"chapter-01/index.html","ordinal":290,"anchor":"search-entry-290","zh":"在一侧修改轮廓或添加缝线，观察另一侧同步变化。","en":"Edit the outline or add a seam on one side and watch the other side update with it.","headingZh":"只画半片，再对称展开","headingEn":"Draft half, then expand symmetrically"},{"page":"chapter-01/index.html","ordinal":291,"anchor":"search-entry-291","zh":"中线有弧度？先删除曲线点","en":"Curved center line? Remove its curve points first","headingZh":"中线有弧度？先删除曲线点","headingEn":"Curved center line? Remove its curve points first"},{"page":"chapter-01/index.html","ordinal":292,"anchor":"search-entry-292","zh":"本例的半片中线带有曲线点，不能直接沿它对称展开。先切换到「编辑板片」工具，选中这条中线。","en":"In this example, the half-pattern's center line contains curve points, so it cannot be used for symmetric expansion yet. Choose Edit Pattern and select that center line.","headingZh":"中线有弧度？先删除曲线点","headingEn":"Curved center line? Remove its curve points first"},{"page":"chapter-01/index.html","ordinal":293,"anchor":"search-entry-293","zh":"在选中的线上右键，选择「删除曲线点」。确认中线恢复为直线。","en":"Right-click the selected line and choose Delete Curve Points. Check that the center edge is straight.","headingZh":"中线有弧度？先删除曲线点","headingEn":"Curved center line? Remove its curve points first"},{"page":"chapter-01/index.html","ordinal":294,"anchor":"search-entry-294","zh":"再右键选择「对称展开编辑（缝纫线）」，沿这条直中线展开另一半。","en":"Right-click again and choose Symmetric Pattern with Sewing to expand the other half across the straight center edge.","headingZh":"中线有弧度？先删除曲线点","headingEn":"Curved center line? Remove its curve points first"},{"page":"chapter-01/index.html","ordinal":295,"anchor":"search-entry-295","zh":"解除联动后，先看选中了多少","en":"After unlinking, check what is selected","headingZh":"解除联动后，先看选中了多少","headingEn":"After unlinking, check what is selected"},{"page":"chapter-01/index.html","ordinal":296,"anchor":"search-entry-296","zh":"需要左右分别调整时，用「编辑板片」工具选中版片，右键选择「解除联动」。之后单侧修改不再同步到另一侧。","en":"When the two sides need different edits, select the pattern with Edit Pattern, right-click, and choose Unlink. Edits on one side no longer mirror to the other.","headingZh":"解除联动后，先看选中了多少","headingEn":"After unlinking, check what is selected"},{"page":"chapter-01/index.html","ordinal":297,"anchor":"search-entry-297","zh":"录屏中的前身片：解除联动后可单独选中一侧并删除，保留另一半。","en":"In the recorded front pattern, one side can be selected and deleted after unlinking, leaving the other half.","headingZh":"解除联动后，先看选中了多少","headingEn":"After unlinking, check what is selected"},{"page":"chapter-01/index.html","ordinal":298,"anchor":"search-entry-298","zh":"录屏中的后身片：点击一侧时两边一起高亮，说明当前仍选中整片；此时按 Delete 会把两边一起删除。","en":"In the recorded back pattern, clicking one side highlights both, so the whole piece is selected. Pressing Delete at that point removes both sides.","headingZh":"解除联动后，先看选中了多少","headingEn":"After unlinking, check what is selected"},{"page":"chapter-01/index.html","ordinal":299,"anchor":"search-entry-299","zh":"解除联动只取消同步编辑，不保证自动把一整片切成两块。删除前一定先看高亮范围。","en":"Unlinking stops mirrored editing, but does not necessarily split one pattern into two pieces. Always check the highlighted area before deleting.","headingZh":"解除联动后，先看选中了多少","headingEn":"After unlinking, check what is selected"},{"page":"chapter-01/index.html","ordinal":300,"anchor":"search-entry-300","zh":"课堂练习｜一片式裁剪","en":"Class project | One-piece cutting","headingZh":"课堂练习｜一片式裁剪","headingEn":"Class project | One-piece cutting"},{"page":"chapter-01/index.html","ordinal":301,"anchor":"search-entry-301","zh":"图文参考：从平面到服装","en":"Image references: from flat pattern to garment","headingZh":"图文参考：从平面到服装","headingEn":"Image references: from flat pattern to garment"},{"page":"chapter-01/index.html","ordinal":302,"anchor":"search-entry-302","zh":"先看平面纸样与折叠示意，再看成衣的造型。下面四张是参考资料，用来观察一片式裁剪如何从平面形成空间；它们不是本课要逐尺寸复刻的纸样。点击图片可放大查看。","en":"Start with the flat patterns and folding diagrams, then compare the finished silhouettes. These four references show ways a one-piece cut can become a three-dimensional garment; they are not measurements to reproduce in this exercise. Select an image to enlarge it.","headingZh":"图文参考：从平面到服装","headingEn":"Image references: from flat pattern to garment"},{"page":"chapter-01/index.html","ordinal":303,"anchor":"search-entry-303","zh":"01 · 一片布如何折成服装","en":"01 · How one piece folds into a garment","headingZh":"图文参考：从平面到服装","headingEn":"Image references: from flat pattern to garment"},{"page":"chapter-01/index.html","ordinal":304,"anchor":"search-entry-304","zh":"02 · 对照裁切、折叠与缝合位置","en":"02 · Compare cutting, folding, and seams","headingZh":"图文参考：从平面到服装","headingEn":"Image references: from flat pattern to garment"},{"page":"chapter-01/index.html","ordinal":305,"anchor":"search-entry-305","zh":"03 · 观察开口与侧边如何形成廓形","en":"03 · See how openings and sides shape the silhouette","headingZh":"图文参考：从平面到服装","headingEn":"Image references: from flat pattern to garment"},{"page":"chapter-01/index.html","ordinal":306,"anchor":"search-entry-306","zh":"04 · 比较平面形状与穿着后的体积","en":"04 · Compare the flat shape with worn volume","headingZh":"图文参考：从平面到服装","headingEn":"Image references: from flat pattern to garment"},{"page":"chapter-01/index.html","ordinal":309,"anchor":"search-entry-309","zh":"用已学过的矩形、内部形状、圆形和对称展开工具，自由探索平面裁片的组合。这次先完成裁片准备：一块连续的大身片，加上前、后两块圆形裁片；后续再考虑连接和模拟。","en":"Explore a garment layout using Rectangle, Internal Shape, Ellipse, and Symmetric Pattern. This stage prepares one continuous body panel plus two circular front/back pieces; sewing and simulation come later.","headingZh":"图文参考：从平面到服装","headingEn":"Image references: from flat pattern to garment"},{"page":"chapter-01/index.html","ordinal":310,"anchor":"search-entry-310","zh":"先建立大身片和圆形裁片","en":"Create the body and circular pieces","headingZh":"先建立大身片和圆形裁片","headingEn":"Create the body and circular pieces"},{"page":"chapter-01/index.html","ordinal":311,"anchor":"search-entry-311","zh":"在 2D 工作区用「矩形」先画大身片的一半，让内侧边线落在模特剪影的中线附近。","en":"Use Rectangle in the 2D workspace to draw half of the body panel, with its inner edge near the avatar silhouette's center line.","headingZh":"先建立大身片和圆形裁片","headingEn":"Create the body and circular pieces"},{"page":"chapter-01/index.html","ordinal":312,"anchor":"search-entry-312","zh":"选中中线，右键选择「对称展开编辑（缝纫线）」，得到完整、左右对称的大身片。","en":"Select the center edge, right-click, and choose Symmetric Pattern with Sewing to expand it into a full, symmetrical body panel.","headingZh":"先建立大身片和圆形裁片","headingEn":"Create the body and circular pieces"},{"page":"chapter-01/index.html","ordinal":313,"anchor":"search-entry-313","zh":"大身片需要留出双臂位置：在片内绘制两个椭圆形内部轮廓，先确定袖口位置。此时红色轮廓只是内部线，尚未切成洞。","en":"Plan space for both arms by drawing two elliptical internal outlines on the body panel. These red outlines are internal lines at this stage, not openings yet.","headingZh":"先建立大身片和圆形裁片","headingEn":"Create the body and circular pieces"},{"page":"chapter-01/index.html","ordinal":314,"anchor":"search-entry-314","zh":"再用「圆形」工具创建前、后两块圆形裁片，放在大身片两侧；录屏中它们显示为椭圆。最后切换 3D 视角，检查三块裁片的位置。","en":"Use Ellipse to create the front and back circular pieces and place them on either side of the body panel. They appear oval in the recording. Finally, check their placement in 3D.","headingZh":"先建立大身片和圆形裁片","headingEn":"Create the body and circular pieces"},{"page":"chapter-01/index.html","ordinal":315,"anchor":"search-entry-315","zh":"自由练习：改变大身片的宽度、袖口间距或圆形裁片的比例。每改一次，观察 2D 与 3D 的对应关系；这一阶段先不要求缝合成衣。","en":"Explore: change the body panel width, armhole spacing, or the proportions of the circular pieces. After each edit, compare the 2D and 3D views. Sewing the garment is not required at this stage.","headingZh":"先建立大身片和圆形裁片","headingEn":"Create the body and circular pieces"},{"page":"chapter-01/index.html","ordinal":316,"anchor":"search-entry-316","zh":"大身片与袖口内部线","en":"Body panel with internal armhole outlines","headingZh":"先建立大身片和圆形裁片","headingEn":"Create the body and circular pieces"},{"page":"chapter-01/index.html","ordinal":317,"anchor":"search-entry-317","zh":"加入前、后圆形裁片","en":"Add front and back circular pieces","headingZh":"先建立大身片和圆形裁片","headingEn":"Create the body and circular pieces"},{"page":"chapter-01/index.html","ordinal":319,"anchor":"search-entry-319","zh":"接下来：开一个小领口","en":"Next: make a small neckline opening","headingZh":"接下来：开一个小领口","headingEn":"Next: make a small neckline opening"},{"page":"chapter-01/index.html","ordinal":320,"anchor":"search-entry-320","zh":"先选中大身片，用「编辑板片」右键解除联动。领口位于中线附近；若左右仍联动，同一位置的操作可能重叠。","en":"Select the body panel and unlink its symmetric editing with Edit Pattern. The neckline sits near the center line, where mirrored edits could overlap.","headingZh":"接下来：开一个小领口","headingEn":"Next: make a small neckline opening"},{"page":"chapter-01/index.html","ordinal":321,"anchor":"search-entry-321","zh":"在大身片内部、模特颈部对应的位置画一个小圆形内部轮廓。选中它，右键「转化为洞」；也可用「切断」分出内侧裁片，再移除内侧裁片。","en":"Draw a small circular internal shape where the avatar's neck meets the body panel. Select it and choose Convert to Hole, or Cut it and remove the separated inner piece.","headingZh":"接下来：开一个小领口","headingEn":"Next: make a small neckline opening"},{"page":"chapter-01/index.html","ordinal":322,"anchor":"search-entry-322","zh":"本练习暂不考虑拉链或纽扣开口，因此领口只要能让模特颈部通过即可，不必开得太大。回到 3D 窗口观察位置，用 Gizmo 稍作调整。","en":"This exercise does not yet plan a zipper or button opening, so the neckline only needs to clear the avatar's neck. Check it in 3D and adjust the panel slightly with the Gizmo.","headingZh":"接下来：开一个小领口","headingEn":"Next: make a small neckline opening"},{"page":"chapter-01/index.html","ordinal":324,"anchor":"search-entry-324","zh":"连接缝线，再开袖口","en":"Sew the pieces, then open the armholes","headingZh":"连接缝线，再开袖口","headingEn":"Sew the pieces, then open the armholes"},{"page":"chapter-01/index.html","ordinal":325,"anchor":"search-entry-325","zh":"使用「自由缝纫」，在大身片边线上依次确定起点和终点，再沿对应圆形裁片的弧边选择起点、终点。前后两侧分别建立缝纫关系。","en":"Use Free Sewing to choose a start and end point on the body panel edge, then a corresponding start and end along the circular piece's curved edge. Repeat for the front and back.","headingZh":"连接缝线，再开袖口","headingEn":"Sew the pieces, then open the armholes"},{"page":"chapter-01/index.html","ordinal":326,"anchor":"search-entry-326","zh":"这次允许两条缝合边长度不同，目的是在模拟时尝试抽褶。重点检查 3D 窗口的彩色连接线：起止顺序应一致，线条不要交叉。","en":"The sewn lengths may differ in this exercise to explore gathers during simulation. Check the colored connection lines in 3D: their start/end order should match and the lines should not cross.","headingZh":"连接缝线，再开袖口","headingEn":"Sew the pieces, then open the armholes"},{"page":"chapter-01/index.html","ordinal":327,"anchor":"search-entry-327","zh":"大身片上的两个红色椭圆目前只是内部线，布料仍挡住手臂。逐个选中它们，右键「转化为洞」；也可以「切断」后移走内侧小裁片。确认 2D 中能透出背景网格、3D 中也看得到开口，再检查开口是否对准模特手臂。","en":"The two red ellipses are still internal lines, so the cloth blocks the arms. Select each one and choose Convert to Hole, or Cut and move away the small inner piece. Confirm that the 2D grid shows through and that each 3D opening lines up with an arm.","headingZh":"连接缝线，再开袖口","headingEn":"Sew the pieces, then open the armholes"},{"page":"chapter-01/index.html","ordinal":328,"anchor":"search-entry-328","zh":"开始模拟，整理穿过袖口的手臂","en":"Simulate and guide the arms through the openings","headingZh":"开始模拟，整理穿过袖口的手臂","headingEn":"Simulate and guide the arms through the openings"},{"page":"chapter-01/index.html","ordinal":329,"anchor":"search-entry-329","zh":"缝线方向和三个开口检查无误后，按空格键开始模拟。版片落到模特身上，观察面料是否与身体相交。","en":"Once the sewing direction and three openings look correct, press Space to start Simulation. Watch the pieces settle and check whether the cloth intersects the avatar.","headingZh":"开始模拟，整理穿过袖口的手臂","headingEn":"Simulate and guide the arms through the openings"},{"page":"chapter-01/index.html","ordinal":330,"anchor":"search-entry-330","zh":"如果大身片太软、容易穿进模特身体，再按空格暂停。选中大身片，右键选择「硬化」；这是临时加硬，方便把版片撑开、调整位置，之后也可以右键解除硬化。","en":"If the body panel is too soft and intersects the avatar, press Space again to pause. Select the body panel, right-click, and choose Strengthen. This temporarily stiffens it for easier handling and can be undone later.","headingZh":"开始模拟，整理穿过袖口的手臂","headingEn":"Simulate and guide the arms through the openings"},{"page":"chapter-01/index.html","ordinal":331,"anchor":"search-entry-331","zh":"重新按空格继续模拟。若手臂仍被布料挡住，在 3D 窗口耐心地拖动袖口边缘，一点点引导布料绕过手臂，让手从开口穿出。需要时随时暂停再调整。","en":"Press Space to resume. If an arm is still trapped by the cloth, gently drag the armhole edge in 3D and guide the fabric around the arm until the hand emerges. Pause and adjust whenever needed.","headingZh":"开始模拟，整理穿过袖口的手臂","headingEn":"Simulate and guide the arms through the openings"},{"page":"chapter-01/index.html","ordinal":333,"anchor":"search-entry-333","zh":"用眼睛判断布量，再圆顺大身片四角","en":"Judge the volume by eye, then smooth the corners","headingZh":"用眼睛判断布量，再圆顺大身片四角","headingEn":"Judge the volume by eye, then smooth the corners"},{"page":"chapter-01/index.html","ordinal":334,"anchor":"search-entry-334","zh":"这一节先不以固定尺寸限制创作。旋转 3D 视角，看布料堆叠与褶量是否合心意；如果想要更多垂褶，暂停模拟，在 2D 放大相应裁片，再继续观察。","en":"Explore without a fixed target measurement. Orbit the 3D view and judge the fabric volume and gathers by eye. For more drape, pause Simulation, enlarge the relevant pattern in 2D, then inspect again.","headingZh":"用眼睛判断布量，再圆顺大身片四角","headingEn":"Judge the volume by eye, then smooth the corners"},{"page":"chapter-01/index.html","ordinal":335,"anchor":"search-entry-335","zh":"想让大身片四角更柔和时，长按「编辑板片」工具，选择「生成圆顺曲线」。","en":"To soften the body panel corners, long-press Edit Pattern and choose Create Smooth Curve.","headingZh":"用眼睛判断布量，再圆顺大身片四角","headingEn":"Judge the volume by eye, then smooth the corners"},{"page":"chapter-01/index.html","ordinal":336,"anchor":"search-entry-336","zh":"把鼠标放在角点上，按住并拖动，让相邻两条边过渡为圆弧。观察 3D 外轮廓，按喜欢的弧度调整。","en":"Hover over a corner, then click and drag to round the transition between its two adjoining edges. Judge the curve in the 3D silhouette.","headingZh":"用眼睛判断布量，再圆顺大身片四角","headingEn":"Judge the volume by eye, then smooth the corners"},{"page":"chapter-01/index.html","ordinal":337,"anchor":"search-entry-337","zh":"此前已经解除对称联动，左右角不会自动同步；需要分别操作。调整完再按空格模拟，检查新的垂坠与袖口位置。","en":"Because symmetric editing was unlinked earlier, changes to one side will not mirror automatically. Round the corners on both sides, then press Space to simulate and inspect the new drape and armholes.","headingZh":"用眼睛判断布量，再圆顺大身片四角","headingEn":"Judge the volume by eye, then smooth the corners"},{"page":"chapter-01/index.html","ordinal":340,"anchor":"search-entry-340","zh":"再缝合后片两侧","en":"Sew the back panel along both sides","headingZh":"再缝合后片两侧","headingEn":"Sew the back panel along both sides"},{"page":"chapter-01/index.html","ordinal":341,"anchor":"search-entry-341","zh":"从背面再看一次造型：如果把后片的两侧与大身片相连，布料会更完整地围住身体，像一件轻盈的万圣节幽灵装。这里最容易出错的是两条缝线的起止顺序。","en":"Check the silhouette from behind. Joining both sides of the back panel to the body panel wraps the fabric around the avatar, giving it a playful ghost-like shape. Pay close attention to the start and end order of each seam.","headingZh":"再缝合后片两侧","headingEn":"Sew the back panel along both sides"},{"page":"chapter-01/index.html","ordinal":342,"anchor":"search-entry-342","zh":"先在 3D 窗口点击要缝的板片或边缘，留意出现的蓝色高亮点；2D 工作区对应的板片上也会显示相应位置。对照两边，确认这条边的前后与起点、终点。","en":"Click the piece or edge you plan to sew in 3D and note the blue highlighted point. Its corresponding position appears on the 2D pattern. Use both views to identify the matching edge and its start and end.","headingZh":"再缝合后片两侧","headingEn":"Sew the back panel along both sides"},{"page":"chapter-01/index.html","ordinal":343,"anchor":"search-entry-343","zh":"选择「自由缝纫」，按相同方向依次指定第一条边的起点、终点，再指定对应边的起点、终点。缝第二条边时，边操作边看 3D：湖蓝色高亮的是当前正在指定的缝纫边，借它检查是否选对侧边、顺序是否一致。","en":"Choose Free Sewing. Set the start and end on one edge, then the matching start and end on the other edge in the same direction. While sewing the second side, watch the cyan-highlighted active edge in 3D to confirm the edge and seam direction.","headingZh":"再缝合后片两侧","headingEn":"Sew the back panel along both sides"},{"page":"chapter-01/index.html","ordinal":344,"anchor":"search-entry-344","zh":"左右两侧都完成后，再看 3D 的连接线是否交叉；若方向有误，先调整缝线。最后按空格模拟，观察后片与大身片合拢后的垂坠。","en":"Repeat on both sides. Check that the 3D connection lines do not cross, correcting any reversed seam before pressing Space to simulate and inspect the drape of the joined panels.","headingZh":"再缝合后片两侧","headingEn":"Sew the back panel along both sides"},{"page":"chapter-01/index.html","ordinal":345,"anchor":"search-entry-345","zh":"官方资料与图片说明","en":"Official references & image notes","headingZh":"官方资料与图片说明","headingEn":"Official references & image notes"},{"page":"chapter-01/index.html","ordinal":346,"anchor":"search-entry-346","zh":"操作说明参考 CLO 官方帮助中心。二维工具卡片与三维 Gizmo、模块库、模拟课程使用实机截图和课堂录屏；缝纫和 3D 笔课程使用本机 CLO 2025.0.128 的工具截图与录屏。","en":"Instructions reference the CLO Help Center. The 2D lessons, Gizmo, Module Library, and Simulation use actual captures and classroom recordings. The sewing and 3D Pen lessons use CLO 2025.0.128 tool captures and recordings.","headingZh":"官方资料与图片说明","headingEn":"Official references & image notes"},{"page":"chapter-01/index.html","ordinal":347,"anchor":"search-entry-347","zh":"关于 CLO3D","en":"About CLO3D","headingZh":"关于 CLO3D","headingEn":"About CLO3D"},{"page":"chapter-01/index.html","ordinal":348,"anchor":"search-entry-348","zh":"想查看完整的图文讲义、工具对照表和资料链接？点此单独阅读，读完可返回本章操作教程。","en":"Open the complete illustrated notes, tool tables, and reference links in a separate page. You can return to this lesson at any time.","headingZh":"关于 CLO3D","headingEn":"About CLO3D"},{"page":"chapter-01/about-clo3d.html","ordinal":3,"anchor":"search-entry-3","zh":"第一章 · 详细图文讲义","en":"Chapter 01 · Complete Illustrated Notes","headingZh":"第一章 · 详细图文讲义","headingEn":"Chapter 01 · Complete Illustrated Notes"},{"page":"chapter-01/about-clo3d.html","ordinal":4,"anchor":"search-entry-4","zh":"补充收录此前 CLO3D BEGINNER’S GUIDE 的讲解、工具表格、课堂英文表达和配图参考。各章节的 CLO 截图均已存为本地资源，并与对应讲解配对。","en":"Expanded explanations, tool tables, classroom phrases and image references from the original beginner's guide. All chapter screenshots are stored locally and paired with the relevant lesson text.","headingZh":"第一章 · 详细图文讲义","headingEn":"Chapter 01 · Complete Illustrated Notes"},{"page":"chapter-01/about-clo3d.html","ordinal":5,"anchor":"search-entry-5","zh":"软件界面详解","en":"Software Interface","headingZh":"软件界面详解","headingEn":"Software Interface"},{"page":"chapter-01/about-clo3d.html","ordinal":6,"anchor":"search-entry-6","zh":"CLO3D 可同时显示二维版片与三维服装。2D Pattern Window 用于绘制和编辑版片，3D Garment Window 用于检查穿着、视角和模拟效果。Library 提供资源，Object Browser 管理对象，而 Property Editor 用来调整选中对象的参数。","en":"CLO3D displays 2D patterns and 3D garments side by side. The 2D Pattern Window creates and edits patterns, while the 3D Garment Window displays fit and simulation. Library contains assets, Object Browser organizes objects, and Property Editor modifies the selected object.","headingZh":"软件界面详解","headingEn":"Software Interface"},{"page":"chapter-01/about-clo3d.html","ordinal":7,"anchor":"search-entry-7","zh":"Object Browser 与 Property Editor 的区别尤为重要：前者主要用于查找和选取对象，后者用于编辑它的属性。单击不同面料，观察 Property Editor 中的参数变化。","en":"A key distinction is that Object Browser selects and manages objects, while Property Editor changes their settings. Select different fabrics and observe the available properties.","headingZh":"软件界面详解","headingEn":"Software Interface"},{"page":"chapter-01/about-clo3d.html","ordinal":20,"anchor":"search-entry-20","zh":"二维版片工具操作","en":"Working with 2D Tools","headingZh":"二维版片工具操作","headingEn":"Working with 2D Tools"},{"page":"chapter-01/about-clo3d.html","ordinal":21,"anchor":"search-entry-21","zh":"先从 Transform Pattern 和 Edit Pattern 开始。Transform Pattern 用于调整整片版片的位置、旋转或缩放，而 Edit Pattern 用于改变点、边线和轮廓；不要为了修改领口弧度而缩放整块衣片。Rectangle 适合规则形状，Polygon 适合自由轮廓，Ellipse 适合圆形或椭圆形。","en":"Begin with Transform Pattern and Edit Pattern. Transform Pattern moves, rotates or scales an entire piece; Edit Pattern modifies points, segments and contours. Do not resize an entire pattern to adjust a neckline. Rectangle makes regular shapes, Polygon custom contours, and Ellipse circular shapes.","headingZh":"二维版片工具操作","headingEn":"Working with 2D Tools"},{"page":"chapter-01/about-clo3d.html","ordinal":22,"anchor":"search-entry-22","zh":"还应认识 Add Point / Split Line（添加点/分割线）、Edit Curvature（编辑曲率）和 Internal Line（内部线）。练习时先画一个矩形，再通过编辑点和曲线将它改为不规则轮廓。","en":"Also recognize Add Point / Split Line, Edit Curvature and Internal Line. Practice by drawing a rectangle, then modifying its points and curved edges.","headingZh":"二维版片工具操作","headingEn":"Working with 2D Tools"},{"page":"chapter-01/about-clo3d.html","ordinal":37,"anchor":"search-entry-37","zh":"三维选择、安排与模拟","en":"3D Placement & Simulation","headingZh":"三维选择、安排与模拟","headingEn":"3D Placement & Simulation"},{"page":"chapter-01/about-clo3d.html","ordinal":38,"anchor":"search-entry-38","zh":"在三维空间中，Select / Move 用于选择并调整版片，Gizmo 是控制移动与旋转方向的操纵器，Arrangement 用于将版片安排在模特附近。学生必须区分 Move the View（移动观察视角）和 Move the Object（改变对象位置）。","en":"In 3D, Select / Move picks and positions patterns, Gizmo controls movement and rotation directions, and Arrangement places pieces near an avatar. Students should distinguish Move the View from Move the Object.","headingZh":"三维选择、安排与模拟","headingEn":"3D Placement & Simulation"},{"page":"chapter-01/about-clo3d.html","ordinal":39,"anchor":"search-entry-39","zh":"Simulation 根据版片、缝纫、重力与碰撞计算布料垂坠。启动前先确认版片位置与缝合关系，否则版片可能掉落。不同版本的按钮与快捷键可能略有不同。","en":"Simulation calculates drape using patterns, sewing, gravity and collision. Before starting it, check placement and sewing; unconnected pieces may fall. Button locations and shortcuts can vary by version.","headingZh":"三维选择、安排与模拟","headingEn":"3D Placement & Simulation"},{"page":"chapter-01/about-clo3d.html","ordinal":50,"anchor":"search-entry-50","zh":"缝纫工具操作","en":"Connecting Pattern Pieces","headingZh":"缝纫工具操作","headingEn":"Connecting Pattern Pieces"},{"page":"chapter-01/about-clo3d.html","ordinal":51,"anchor":"search-entry-51","zh":"Segment Sewing（线段缝纫）将两块版片的完整边线连接；先单击第一条线段，再单击第二条线段创建缝纫关系。Free Sewing（自由缝纫）允许自行指定缝合的起始点与终点，适合局部缝合需求。","en":"Segment Sewing connects two complete pattern edges: click one segment, then the other. Free Sewing lets you choose custom start and end points for localized stitching.","headingZh":"缝纫工具操作","headingEn":"Connecting Pattern Pieces"},{"page":"chapter-01/about-clo3d.html","ordinal":52,"anchor":"search-entry-52","zh":"缝纫在二维版片之间建立连接关系，随后 Simulation 才会依据这些连接来计算布料。对于新手，建议先练习两块简单矩形布料的边缘缝合。","en":"Sewing creates relationships between 2D pattern pieces; Simulation then uses those relationships to calculate their 3D behavior. Beginners can practice on two simple rectangular pieces.","headingZh":"缝纫工具操作","headingEn":"Connecting Pattern Pieces"},{"page":"chapter-01/about-clo3d.html","ordinal":55,"anchor":"search-entry-55","zh":"官方教程与动态演示链接","en":"Official Guides & Motion Demonstrations","headingZh":"官方教程与动态演示链接","headingEn":"Official Guides & Motion Demonstrations"},{"page":"chapter-01/about-clo3d.html","ordinal":56,"anchor":"search-entry-56","zh":"上方四段鼠标与视角演示已使用课堂实录视频。下方链接可打开官方资料继续学习；后续课程可再加入版片编辑、缝纫与模拟的录屏。","en":"The four mouse and view demonstrations above are classroom recordings. The links below open official references for further study. Future lessons can add recordings for pattern editing, sewing, and simulation.","headingZh":"官方教程与动态演示链接","headingEn":"Official Guides & Motion Demonstrations"},{"page":"chapter-01/reset-3d-pattern.html","ordinal":2,"anchor":"search-entry-2","zh":"重置 3D 版片","en":"Reset 3D Pattern","headingZh":"重置 3D 版片","headingEn":"Reset 3D Pattern"},{"page":"chapter-01/reset-3d-pattern.html","ordinal":3,"anchor":"search-entry-3","zh":"模拟出错后，先按空格键暂停。重置可让选中的版片恢复平展，但不保证回到原来的空间位置。","en":"If Simulation goes wrong, press Space to pause. Resetting flattens the selected pieces, but may not restore their former positions.","headingZh":"重置 3D 版片","headingEn":"Reset 3D Pattern"},{"page":"chapter-01/reset-3d-pattern.html","ordinal":4,"anchor":"search-entry-4","zh":"在 2D 工作区框选需要复原的版片。编辑前先选中目标。","en":"Box-select the pieces to restore in the 2D workspace. Always select your target before editing.","headingZh":"重置 3D 版片","headingEn":"Reset 3D Pattern"},{"page":"chapter-01/reset-3d-pattern.html","ordinal":5,"anchor":"search-entry-5","zh":"鼠标移到 3D 窗口，在选中的版片上右键，选择「重置 3D 版片」。","en":"Move to the 3D window, right-click the selected piece, and choose Reset 3D Pattern.","headingZh":"重置 3D 版片","headingEn":"Reset 3D Pattern"},{"page":"chapter-01/reset-3d-pattern.html","ordinal":6,"anchor":"search-entry-6","zh":"检查版片是否恢复平展；必要时用 Gizmo 或安排点重新放置，再重新检查缝线方向。","en":"Check that the pieces are flat. Reposition them with the Gizmo or arrangement points if needed, then check the seam directions again.","headingZh":"重置 3D 版片","headingEn":"Reset 3D Pattern"},{"page":"shirt-lesson/index.html","ordinal":5,"anchor":"search-entry-5","zh":"从男士基础版开始，转移省道的量，像用硫酸纸描图一样勾勒无省道上衣板，再切出板片、安排到模特身上并缝合模拟。跟着录屏理解每一步，设计自己的宽松衬衫版型。","en":"Start with a men's basic block, transfer the dart intake, and trace a dartless bodice block as if using tracing paper. Then cut out the new pieces, arrange them on the avatar, sew, and simulate your own relaxed shirt pattern.","headingZh":"男士衬衫版型设计","headingEn":"Men's shirt pattern design"},{"page":"shirt-lesson/index.html","ordinal":33,"anchor":"search-entry-33","zh":"准备版片与模特","en":"Prepare the pattern and avatar","headingZh":"男士衬衫版型设计","headingEn":"Men's shirt pattern design"},{"page":"shirt-lesson/index.html","ordinal":34,"anchor":"search-entry-34","zh":"从男士基础版开始","en":"Start with the men's basic block","headingZh":"从男士基础版开始","headingEn":"Start with the men's basic block"},{"page":"shirt-lesson/index.html","ordinal":35,"anchor":"search-entry-35","zh":"打开课程文件，里面已经有男士基础版片。先加入虚拟模特，再把版片放到模特身上对应的位置，为接下来的版型调整建立 2D 与 3D 的对应关系。","en":"Open the course file containing the men's basic pattern pieces. Add an avatar, then arrange each piece near its corresponding position on the body so the 2D pattern and 3D placement are easy to compare.","headingZh":"从男士基础版开始","headingEn":"Start with the men's basic block"},{"page":"shirt-lesson/index.html","ordinal":36,"anchor":"search-entry-36","zh":"在「文件」菜单打开已有的男士基础版。","en":"Open the prepared men's basic block from the File menu.","headingZh":"从男士基础版开始","headingEn":"Start with the men's basic block"},{"page":"shirt-lesson/index.html","ordinal":37,"anchor":"search-entry-37","zh":"加入虚拟模特；选中板片，在 3D 窗口将它放到相应身体区域。录屏中演示了前片的安排。","en":"Add an avatar. Select a piece and place it near the matching body area in the 3D window. The recording demonstrates positioning a front piece.","headingZh":"从男士基础版开始","headingEn":"Start with the men's basic block"},{"page":"shirt-lesson/index.html","ordinal":38,"anchor":"search-entry-38","zh":"操作视频 · 打开文件、加入模特并安放板片","en":"Demonstration · Open the file, add the avatar, and arrange a piece","headingZh":"从男士基础版开始","headingEn":"Start with the men's basic block"},{"page":"shirt-lesson/index.html","ordinal":39,"anchor":"search-entry-39","zh":"接下来，开始改板片","en":"Next, reshape the pattern","headingZh":"接下来，开始改板片","headingEn":"Next, reshape the pattern"},{"page":"shirt-lesson/index.html","ordinal":40,"anchor":"search-entry-40","zh":"这一步就是版型设计。录屏里的数值只是示范，不必完全照抄；理解松量从哪里收起、又在哪里打开，就能按同样的逻辑设计自己想要的衬衫。","en":"This is the pattern-design stage. The values shown in the recordings are examples, not fixed measurements. Once you understand where ease closes and where it opens, you can use the same logic to shape your own shirt.","headingZh":"接下来，开始改板片","headingEn":"Next, reshape the pattern"},{"page":"shirt-lesson/index.html","ordinal":41,"anchor":"search-entry-41","zh":"胸省 → 领口","en":"Chest dart → Neckline","headingZh":"接下来，开始改板片","headingEn":"Next, reshape the pattern"},{"page":"shirt-lesson/index.html","ordinal":42,"anchor":"search-entry-42","zh":"切出可旋转的小板片","en":"Cut a small piece that can rotate","headingZh":"切出可旋转的小板片","headingEn":"Cut a small piece that can rotate"},{"page":"shirt-lesson/index.html","ordinal":43,"anchor":"search-entry-43","zh":"希望领口多一点松量，就先从胸省省尖向领口切开，让这一块前片可以单独旋转。","en":"To add some ease at the neckline, cut from the chest dart tip to the neckline so this section of the front pattern can rotate independently.","headingZh":"切出可旋转的小板片","headingEn":"Cut a small piece that can rotate"},{"page":"shirt-lesson/index.html","ordinal":44,"anchor":"search-entry-44","zh":"按 G 使用「半片内部线」，从胸省省尖画到领口；双击结束线段。","en":"Press G for Half Pattern Internal Line. Draw from the chest dart tip to the neckline, then double-click to finish the line.","headingZh":"切出可旋转的小板片","headingEn":"Cut a small piece that can rotate"},{"page":"shirt-lesson/index.html","ordinal":45,"anchor":"search-entry-45","zh":"选中这条内部线，右键选择「切断」。切开后得到一块可单独操作的小板片。","en":"Select the internal line, right-click, and choose Cut. The cut creates a small piece you can move separately.","headingZh":"切出可旋转的小板片","headingEn":"Cut a small piece that can rotate"},{"page":"shirt-lesson/index.html","ordinal":46,"anchor":"search-entry-46","zh":"操作视频 · 画内部线并切断","en":"Demonstration · Draw an internal line and cut","headingZh":"切出可旋转的小板片","headingEn":"Cut a small piece that can rotate"},{"page":"shirt-lesson/index.html","ordinal":47,"anchor":"search-entry-47","zh":"关闭一处 · 打开另一处","en":"Close one area · Open another","headingZh":"切出可旋转的小板片","headingEn":"Cut a small piece that can rotate"},{"page":"shirt-lesson/index.html","ordinal":48,"anchor":"search-entry-48","zh":"合胸省，打开领口","en":"Close the chest dart and open the neckline","headingZh":"合胸省，打开领口","headingEn":"Close the chest dart and open the neckline"},{"page":"shirt-lesson/index.html","ordinal":49,"anchor":"search-entry-49","zh":"让原来胸省的两侧在省尖处对齐，再以省尖为中心旋转小板片。胸省收小的量，会转移到领口形成新的开口。","en":"Align the two sides of the original chest dart at its tip, then rotate the small piece around that point. As the chest dart becomes smaller, an opening appears at the neckline.","headingZh":"合胸省，打开领口","headingEn":"Close the chest dart and open the neckline"},{"page":"shirt-lesson/index.html","ordinal":50,"anchor":"search-entry-50","zh":"将原来的两个省道点尽量重合；拖动时按 Ctrl（Mac 按 Command）可细调位置。","en":"Bring the original dart points together. Hold Ctrl (Command on Mac) while dragging for finer adjustment.","headingZh":"合胸省，打开领口","headingEn":"Close the chest dart and open the neckline"},{"page":"shirt-lesson/index.html","ordinal":51,"anchor":"search-entry-51","zh":"双击旋转中心，将它移到省尖，再旋转板片。观察领口打开的宽度，按想要的松量决定旋转角度，无须照抄录屏数值。","en":"Double-click the rotation center and move it to the dart tip, then rotate the piece. Choose the angle by the neckline opening you want rather than copying the number in the recording.","headingZh":"合胸省，打开领口","headingEn":"Close the chest dart and open the neckline"},{"page":"shirt-lesson/index.html","ordinal":52,"anchor":"search-entry-52","zh":"操作视频 · 重设旋转中心并打开领口","en":"Demonstration · Move the pivot and open the neckline","headingZh":"合胸省，打开领口","headingEn":"Close the chest dart and open the neckline"},{"page":"shirt-lesson/index.html","ordinal":53,"anchor":"search-entry-53","zh":"肩省 → 领口与袖窿","en":"Shoulder dart → Neckline & armhole","headingZh":"合胸省，打开领口","headingEn":"Close the chest dart and open the neckline"},{"page":"shirt-lesson/index.html","ordinal":54,"anchor":"search-entry-54","zh":"为肩省转移做两处切口","en":"Make two cuts from the shoulder dart","headingZh":"为肩省转移做两处切口","headingEn":"Make two cuts from the shoulder dart"},{"page":"shirt-lesson/index.html","ordinal":55,"anchor":"search-entry-55","zh":"前片的袖窿也需要松量。和前一步同理，以肩省省尖为起点，分别向领口与袖窿画内部线，再把两条线切开。","en":"The front armhole also needs ease. As before, start at the shoulder dart tip. Draw one internal line to the neckline and another to the armhole, then cut along both lines.","headingZh":"为肩省转移做两处切口","headingEn":"Make two cuts from the shoulder dart"},{"page":"shirt-lesson/index.html","ordinal":56,"anchor":"search-entry-56","zh":"按 G，从肩省省尖向领口画线；再从同一省尖向袖窿画线。每条线双击结束。","en":"Press G and draw a line from the shoulder dart tip to the neckline, then another from the same tip to the armhole. Double-click to finish each line.","headingZh":"为肩省转移做两处切口","headingEn":"Make two cuts from the shoulder dart"},{"page":"shirt-lesson/index.html","ordinal":57,"anchor":"search-entry-57","zh":"分别选中两条内部线，右键「切断」，得到可围绕省尖旋转的小板片。","en":"Select each internal line and use Cut from the right-click menu. This produces pieces that can rotate around the dart tip.","headingZh":"为肩省转移做两处切口","headingEn":"Make two cuts from the shoulder dart"},{"page":"shirt-lesson/index.html","ordinal":58,"anchor":"search-entry-58","zh":"操作视频 · 肩省画线与切断","en":"Demonstration · Draw and cut from the shoulder dart","headingZh":"为肩省转移做两处切口","headingEn":"Make two cuts from the shoulder dart"},{"page":"shirt-lesson/index.html","ordinal":59,"anchor":"search-entry-59","zh":"把松量放到想要的位置","en":"Place the ease where you want it","headingZh":"为肩省转移做两处切口","headingEn":"Make two cuts from the shoulder dart"},{"page":"shirt-lesson/index.html","ordinal":60,"anchor":"search-entry-60","zh":"先开领口，再转到袖窿","en":"Open the neckline, then the armhole","headingZh":"先开领口，再转到袖窿","headingEn":"Open the neckline, then the armhole"},{"page":"shirt-lesson/index.html","ordinal":61,"anchor":"search-entry-61","zh":"把切出的板片重新以肩省省尖对齐。先给领口留一点开口，再旋转左侧小板片，关闭肩省，让更多松量转移到袖窿。","en":"Align the cut pieces again at the shoulder dart tip. Open the neckline slightly first, then rotate the left piece to close the shoulder dart and transfer more ease to the armhole.","headingZh":"先开领口，再转到袖窿","headingEn":"Open the neckline, then the armhole"},{"page":"shirt-lesson/index.html","ordinal":62,"anchor":"search-entry-62","zh":"对齐省尖，先旋转靠领口的小板片，留出少量领口松量。","en":"Align the dart tips and rotate the neckline-side piece to leave a small neckline opening.","headingZh":"先开领口，再转到袖窿","headingEn":"Open the neckline, then the armhole"},{"page":"shirt-lesson/index.html","ordinal":63,"anchor":"search-entry-63","zh":"再旋转左侧小板片，使肩省闭合，同时观察袖窿处打开的量。按希望的造型调整，不必追求录屏里的角度。","en":"Rotate the left piece to close the shoulder dart while watching the armhole opening. Adjust it for the shape you want rather than matching the recorded angle.","headingZh":"先开领口，再转到袖窿","headingEn":"Open the neckline, then the armhole"},{"page":"shirt-lesson/index.html","ordinal":64,"anchor":"search-entry-64","zh":"版型小贴士","en":"Pattern tip","headingZh":"先开领口，再转到袖窿","headingEn":"Open the neckline, then the armhole"},{"page":"shirt-lesson/index.html","ordinal":65,"anchor":"search-entry-65","zh":"一般会在前片领口留出一些松量；后片领口可视设计需要决定是否增加。避免只给后片领口加松量、前片却完全不加。","en":"The front neckline usually receives some ease. Adding ease to the back neckline depends on the design. Avoid adding ease only at the back while leaving the front neckline unchanged.","headingZh":"先开领口，再转到袖窿","headingEn":"Open the neckline, then the armhole"},{"page":"shirt-lesson/index.html","ordinal":66,"anchor":"search-entry-66","zh":"操作视频 · 关闭肩省并调整袖窿松量","en":"Demonstration · Close the shoulder dart and adjust armhole ease","headingZh":"先开领口，再转到袖窿","headingEn":"Open the neckline, then the armhole"},{"page":"shirt-lesson/index.html","ordinal":67,"anchor":"search-entry-67","zh":"像硫酸纸一样描版","en":"Trace the pattern like tracing paper","headingZh":"先开领口，再转到袖窿","headingEn":"Open the neckline, then the armhole"},{"page":"shirt-lesson/index.html","ordinal":68,"anchor":"search-entry-68","zh":"先勾勒直线轮廓","en":"Trace the straight edges first","headingZh":"先勾勒直线轮廓","headingEn":"Trace the straight edges first"},{"page":"shirt-lesson/index.html","ordinal":69,"anchor":"search-entry-69","zh":"省道的量已经分配到领口和袖窿。现在在原板片上盖一片矩形，把调整后的轮廓转描到这片新板片上。","en":"The dart intake has been distributed to the neckline and armhole. Place a rectangle over the original pieces and trace their adjusted outlines onto this new pattern piece.","headingZh":"先勾勒直线轮廓","headingEn":"Trace the straight edges first"},{"page":"shirt-lesson/index.html","ordinal":70,"anchor":"search-entry-70","zh":"按 S 创建矩形，让矩形覆盖要描绘的板片；从左上角的「服装渲染类型」菜单选择「半透明表面」，使下面的原板片可见。","en":"Press S to create a rectangle over the pieces you want to trace. From Garment Rendering Type at the upper left, choose Semi-Transparent Surface so the original pieces remain visible underneath.","headingZh":"先勾勒直线轮廓","headingEn":"Trace the straight edges first"},{"page":"shirt-lesson/index.html","ordinal":71,"anchor":"search-entry-71","zh":"按 I 使用图示工具，依次点击原板片上相连、未被打断的直线边；按 Enter 结束。新矩形上会出现红色内部线。","en":"Press I to use the tool shown here. Click the connected, unbroken straight edges of the original pattern in sequence, then press Enter. Red internal lines appear on the new rectangle.","headingZh":"先勾勒直线轮廓","headingEn":"Trace the straight edges first"},{"page":"shirt-lesson/index.html","ordinal":72,"anchor":"search-entry-72","zh":"操作视频 · 用半透明矩形描直线","en":"Demonstration · Trace straight edges on a semi-transparent rectangle","headingZh":"先勾勒直线轮廓","headingEn":"Trace the straight edges first"},{"page":"shirt-lesson/index.html","ordinal":73,"anchor":"search-entry-73","zh":"补齐领口与袖窿","en":"Complete the neckline and armhole","headingZh":"先勾勒直线轮廓","headingEn":"Trace the straight edges first"},{"page":"shirt-lesson/index.html","ordinal":74,"anchor":"search-entry-74","zh":"画曲线，完成无省道上衣板","en":"Draw the curves to finish the dartless block","headingZh":"画曲线，完成无省道上衣板","headingEn":"Draw the curves to finish the dartless block"},{"page":"shirt-lesson/index.html","ordinal":75,"anchor":"search-entry-75","zh":"直线确定后，用「内部多边形／线」补画领口、袖窿等曲线。点不用很多，重点是让线条顺着原板片的弧度走。","en":"Once the straight edges are in place, use Internal Polygon/Line to add the neckline, armhole, and other curves. You need only a few points; focus on following the original pattern's smooth contours.","headingZh":"画曲线，完成无省道上衣板","headingEn":"Draw the curves to finish the dartless block"},{"page":"shirt-lesson/index.html","ordinal":76,"anchor":"search-entry-76","zh":"按 G 选择「内部多边形／线」，沿曲线依次落点；在需要弧度的位置按住鼠标拖动，调整曲线方向。","en":"Press G for Internal Polygon/Line. Add points along each curve; click and drag where the line needs a bend to shape its direction.","headingZh":"画曲线，完成无省道上衣板","headingEn":"Draw the curves to finish the dartless block"},{"page":"shirt-lesson/index.html","ordinal":77,"anchor":"search-entry-77","zh":"视图不够用时，按住鼠标滚轮拖动画布。曲线画完按 Enter 收尾，检查前后片轮廓是否顺畅衔接。","en":"Hold the middle mouse button and drag to pan the canvas when you need more room. Press Enter to finish each curve, then check that the front and back outlines connect smoothly.","headingZh":"画曲线，完成无省道上衣板","headingEn":"Draw the curves to finish the dartless block"},{"page":"shirt-lesson/index.html","ordinal":78,"anchor":"search-entry-78","zh":"操作视频 · 描绘曲线并完成轮廓","en":"Demonstration · Draw the curves and complete the outline","headingZh":"画曲线，完成无省道上衣板","headingEn":"Draw the curves to finish the dartless block"},{"page":"shirt-lesson/index.html","ordinal":79,"anchor":"search-entry-79","zh":"这一步的结果","en":"Result of this step","headingZh":"画曲线，完成无省道上衣板","headingEn":"Draw the curves to finish the dartless block"},{"page":"shirt-lesson/index.html","ordinal":81,"anchor":"search-entry-81","zh":"从描线到新裁片","en":"From traced lines to new pieces","headingZh":"画曲线，完成无省道上衣板","headingEn":"Draw the curves to finish the dartless block"},{"page":"shirt-lesson/index.html","ordinal":82,"anchor":"search-entry-82","zh":"切出无省道板片","en":"Cut out the dartless pieces","headingZh":"切出无省道板片","headingEn":"Cut out the dartless pieces"},{"page":"shirt-lesson/index.html","ordinal":83,"anchor":"search-entry-83","zh":"描线完成后，旧板片只是参照。删去先前调整的板片，保留带有红色内部线的矩形，再沿新轮廓切出需要的板片。","en":"Once tracing is complete, the earlier adjusted pieces have served as references. Delete them, keep the rectangle with red internal lines, and cut the new pieces along those outlines.","headingZh":"切出无省道板片","headingEn":"Cut out the dartless pieces"},{"page":"shirt-lesson/index.html","ordinal":84,"anchor":"search-entry-84","zh":"删除先前调整的板片，只留下最后用于描线的矩形。","en":"Delete the earlier adjusted pattern pieces, leaving only the rectangle used for tracing.","headingZh":"切出无省道板片","headingEn":"Cut out the dartless pieces"},{"page":"shirt-lesson/index.html","ordinal":85,"anchor":"search-entry-85","zh":"按 I 切换到前一步使用的工具，框选要切出的轮廓；右键选择「切断」。","en":"Press I to return to the tool used in the previous step. Marquee-select the outlines to separate, then right-click and choose Cut.","headingZh":"切出无省道板片","headingEn":"Cut out the dartless pieces"},{"page":"shirt-lesson/index.html","ordinal":86,"anchor":"search-entry-86","zh":"删去矩形中多余的部分，只保留勾勒出的前后板片。","en":"Delete the unwanted areas of the rectangle and keep only the newly traced front and back pieces.","headingZh":"切出无省道板片","headingEn":"Cut out the dartless pieces"},{"page":"shirt-lesson/index.html","ordinal":87,"anchor":"search-entry-87","zh":"操作视频 · 保留描线矩形并切出新板片","en":"Demonstration · Keep the traced rectangle and cut the new pieces","headingZh":"切出无省道板片","headingEn":"Cut out the dartless pieces"},{"page":"shirt-lesson/index.html","ordinal":88,"anchor":"search-entry-88","zh":"整理 2D 与 3D 工作区","en":"Prepare the 2D and 3D workspaces","headingZh":"切出无省道板片","headingEn":"Cut out the dartless pieces"},{"page":"shirt-lesson/index.html","ordinal":89,"anchor":"search-entry-89","zh":"对称关联，再安排到模特身上","en":"Link matching pieces and arrange them on the avatar","headingZh":"对称关联，再安排到模特身上","headingEn":"Link matching pieces and arrange them on the avatar"},{"page":"shirt-lesson/index.html","ordinal":90,"anchor":"search-entry-90","zh":"先把新板片排整齐，再建立左右关联。3D 窗口中的安排点可以帮我们快速把板片放到模特对应的位置。","en":"Tidy the new pieces on the 2D canvas, then create linked left and right counterparts. Arrangement points in the 3D window help place each piece near the matching area of the avatar.","headingZh":"对称关联，再安排到模特身上","headingEn":"Link matching pieces and arrange them on the avatar"},{"page":"shirt-lesson/index.html","ordinal":91,"anchor":"search-entry-91","zh":"在 2D 工作区调整板片间距，框选前后两片；按 Ctrl／Command + D，将它们对称关联复制到另一侧。","en":"Space the pieces neatly in the 2D workspace. Marquee-select the front and back pieces, then press Ctrl/Command + D to create symmetrically linked copies on the other side.","headingZh":"对称关联，再安排到模特身上","headingEn":"Link matching pieces and arrange them on the avatar"},{"page":"shirt-lesson/index.html","ordinal":92,"anchor":"search-entry-92","zh":"打开 3D 窗口，并确认虚拟模特已开启「显示安排点」。","en":"Open the 3D window and make sure Show Arrangement Points is enabled for the avatar.","headingZh":"对称关联，再安排到模特身上","headingEn":"Link matching pieces and arrange them on the avatar"},{"page":"shirt-lesson/index.html","ordinal":93,"anchor":"search-entry-93","zh":"点击 2D 工作区中的一片板片，再点击模特身上对应的蓝色安排点；逐片完成安放。","en":"Select a piece in the 2D workspace, then click the matching blue arrangement point on the avatar. Repeat for each piece.","headingZh":"对称关联，再安排到模特身上","headingEn":"Link matching pieces and arrange them on the avatar"},{"page":"shirt-lesson/index.html","ordinal":94,"anchor":"search-entry-94","zh":"操作视频 · 对称关联并安排板片","en":"Demonstration · Link symmetric pieces and arrange them","headingZh":"对称关联，再安排到模特身上","headingEn":"Link matching pieces and arrange them on the avatar"},{"page":"shirt-lesson/index.html","ordinal":95,"anchor":"search-entry-95","zh":"确认缝线方向","en":"Check the sewing direction","headingZh":"对称关联，再安排到模特身上","headingEn":"Link matching pieces and arrange them on the avatar"},{"page":"shirt-lesson/index.html","ordinal":96,"anchor":"search-entry-96","zh":"缝合板片并开始模拟","en":"Sew the pieces and start simulation","headingZh":"缝合板片并开始模拟","headingEn":"Sew the pieces and start simulation"},{"page":"shirt-lesson/index.html","ordinal":97,"anchor":"search-entry-97","zh":"板片放好后，先建立基本的缝纫关系。缝线的起止顺序会影响模拟结果，边缝边在 3D 窗口检查彩色缝纫线。","en":"Once the pieces are arranged, add the basic seams. The direction of each seam affects simulation, so check the colored sewing lines in the 3D window as you work.","headingZh":"缝合板片并开始模拟","headingEn":"Sew the pieces and start simulation"},{"page":"shirt-lesson/index.html","ordinal":98,"anchor":"search-entry-98","zh":"按 N 选择「线缝纫」，依次点击需要连接的两条边，大致缝合侧缝、后中、肩线和前中。","en":"Press N for Segment Sewing. Click each pair of edges to connect the side seams, center back, shoulders, and center front.","headingZh":"缝合板片并开始模拟","headingEn":"Sew the pieces and start simulation"},{"page":"shirt-lesson/index.html","ordinal":99,"anchor":"search-entry-99","zh":"在 3D 窗口检查彩色缝纫线的走向：对应边之间应顺直连接，不要交叉；如果交叉，先调整缝线顺序。","en":"Check the colored sewing lines in 3D. They should connect matching edges without crossing. If they cross, correct the sewing direction before simulating.","headingZh":"缝合板片并开始模拟","headingEn":"Sew the pieces and start simulation"},{"page":"shirt-lesson/index.html","ordinal":100,"anchor":"search-entry-100","zh":"按空格键开始模拟，观察板片如何缝合到模特身上。","en":"Press Space to start simulation and watch the pieces form around the avatar.","headingZh":"缝合板片并开始模拟","headingEn":"Sew the pieces and start simulation"},{"page":"shirt-lesson/index.html","ordinal":101,"anchor":"search-entry-101","zh":"操作视频 · 缝合侧缝、后中、肩线与前中并模拟","en":"Demonstration · Sew the main seams and simulate","headingZh":"缝合板片并开始模拟","headingEn":"Sew the pieces and start simulation"},{"page":"shirt-lesson/index.html","ordinal":102,"anchor":"search-entry-102","zh":"观察宽松版型","en":"Inspect the relaxed silhouette","headingZh":"缝合板片并开始模拟","headingEn":"Sew the pieces and start simulation"},{"page":"shirt-lesson/index.html","ordinal":103,"anchor":"search-entry-103","zh":"硬化板片，检查轮廓","en":"Harden the pieces to inspect the shape","headingZh":"硬化板片，检查轮廓","headingEn":"Harden the pieces to inspect the shape"},{"page":"shirt-lesson/index.html","ordinal":104,"anchor":"search-entry-104","zh":"模拟后，柔软的面料可能暂时遮住版型线条。先把板片硬化，观察宽松上衣的整体轮廓。","en":"After simulation, soft fabric can obscure the shape of the pattern. Harden the pieces temporarily to inspect the overall silhouette of the relaxed top.","headingZh":"硬化板片，检查轮廓","headingEn":"Harden the pieces to inspect the shape"},{"page":"shirt-lesson/index.html","ordinal":105,"anchor":"search-entry-105","zh":"按 Ctrl／Command + A 全选板片，在 3D 窗口右键选择「硬化」。","en":"Press Ctrl/Command + A to select all pieces, then right-click in the 3D window and choose Harden.","headingZh":"硬化板片，检查轮廓","headingEn":"Harden the pieces to inspect the shape"},{"page":"shirt-lesson/index.html","ordinal":106,"anchor":"search-entry-106","zh":"转动视角检查领口、肩线、袖窿与衣身的松量，判断轮廓是否符合自己的设计。","en":"Rotate the view to inspect the neckline, shoulders, armholes, and body ease, and decide whether the shape matches your design.","headingZh":"硬化板片，检查轮廓","headingEn":"Harden the pieces to inspect the shape"},{"page":"shirt-lesson/index.html","ordinal":107,"anchor":"search-entry-107","zh":"操作视频 · 硬化板片并检查版型","en":"Demonstration · Harden the pieces and inspect the pattern","headingZh":"硬化板片，检查轮廓","headingEn":"Harden the pieces to inspect the shape"},{"page":"shirt-lesson/index.html","ordinal":109,"anchor":"search-entry-109","zh":"开始处理板片细节","en":"Refine the pattern pieces","headingZh":"开始处理板片细节","headingEn":"Refine the pattern pieces"},{"page":"shirt-lesson/index.html","ordinal":110,"anchor":"search-entry-110","zh":"基本结构已经完成。接下来回到 2D 工作区，调整比例、修顺线条，并为衬衫增加门襟。","en":"With the basic structure in place, return to the 2D workspace to refine proportions and lines, then add the shirt's front placket.","headingZh":"开始处理板片细节","headingEn":"Refine the pattern pieces"},{"page":"shirt-lesson/index.html","ordinal":111,"anchor":"search-entry-111","zh":"从衣身比例开始","en":"Start with body proportions","headingZh":"开始处理板片细节","headingEn":"Refine the pattern pieces"},{"page":"shirt-lesson/index.html","ordinal":112,"anchor":"search-entry-112","zh":"调整衣长与宽度","en":"Adjust the length and width","headingZh":"调整衣长与宽度","headingEn":"Adjust the length and width"},{"page":"shirt-lesson/index.html","ordinal":113,"anchor":"search-entry-113","zh":"先决定衬衫的长度和宽松程度。此前创建了对称关联板片，因此只需修改一侧的前片或后片，另一侧会同步变化。","en":"Decide the shirt's length and ease first. Because the pieces were linked symmetrically, editing one front or back piece updates its counterpart automatically.","headingZh":"调整衣长与宽度","headingEn":"Adjust the length and width"},{"page":"shirt-lesson/index.html","ordinal":114,"anchor":"search-entry-114","zh":"按 Z 切换到「编辑板片」，选中要调整的边线，拖动它改变衣长或衣身宽度。","en":"Press Z for Edit Pattern, select the edge you want to adjust, and drag it to change the garment length or body width.","headingZh":"调整衣长与宽度","headingEn":"Adjust the length and width"},{"page":"shirt-lesson/index.html","ordinal":115,"anchor":"search-entry-115","zh":"需要一起调整几条边时，先选中一条，再按住 Shift 继续点选其他线段。","en":"To edit several edges together, select the first one, then hold Shift while selecting the other segments.","headingZh":"调整衣长与宽度","headingEn":"Adjust the length and width"},{"page":"shirt-lesson/index.html","ordinal":116,"anchor":"search-entry-116","zh":"在 2D 与 3D 窗口交替检查长度和围度，不必照搬视频里的尺寸。","en":"Compare the length and circumference in the 2D and 3D windows. You do not need to copy the measurements shown in the recording.","headingZh":"调整衣长与宽度","headingEn":"Adjust the length and width"},{"page":"shirt-lesson/index.html","ordinal":117,"anchor":"search-entry-117","zh":"操作视频 · 调整衣长与宽度","en":"Demonstration · Adjust garment length and width","headingZh":"调整衣长与宽度","headingEn":"Adjust the length and width"},{"page":"shirt-lesson/index.html","ordinal":118,"anchor":"search-entry-118","zh":"自由调整造型","en":"Shape the design freely","headingZh":"调整衣长与宽度","headingEn":"Adjust the length and width"},{"page":"shirt-lesson/index.html","ordinal":119,"anchor":"search-entry-119","zh":"修顺袖窿、肩线和后身","en":"Refine the armhole, shoulder, and back","headingZh":"修顺袖窿、肩线和后身","headingEn":"Refine the armhole, shoulder, and back"},{"page":"shirt-lesson/index.html","ordinal":120,"anchor":"search-entry-120","zh":"这一段可以按照自己想要的廓形自由调整。视频示范了袖窿、肩线和后身的修改，重点是边调整边看 3D 效果。","en":"Use this stage to shape the silhouette you want. The recording adjusts the armhole, shoulder, and back; keep checking the 3D result as you edit.","headingZh":"修顺袖窿、肩线和后身","headingEn":"Refine the armhole, shoulder, and back"},{"page":"shirt-lesson/index.html","ordinal":121,"anchor":"search-entry-121","zh":"用「编辑板片」移动点或线，调整袖窿的深度与弧度，再修肩线和后身轮廓。","en":"Use Edit Pattern to move points or lines, adjusting armhole depth and curvature before refining the shoulder line and back outline.","headingZh":"修顺袖窿、肩线和后身","headingEn":"Refine the armhole, shoulder, and back"},{"page":"shirt-lesson/index.html","ordinal":122,"anchor":"search-entry-122","zh":"袖窿加深、放大后，后续袖片也需要与新的袖窿尺寸相匹配；这一段还没有制作袖片。","en":"If you deepen or enlarge the armhole, the sleeve pattern will need to match its new dimensions later. This recording does not create a sleeve yet.","headingZh":"修顺袖窿、肩线和后身","headingEn":"Refine the armhole, shoulder, and back"},{"page":"shirt-lesson/index.html","ordinal":123,"anchor":"search-entry-123","zh":"操作视频 · 调整袖窿与肩线（1.5 倍速）","en":"Demonstration · Refine the armhole and shoulder (1.5× speed)","headingZh":"修顺袖窿、肩线和后身","headingEn":"Refine the armhole, shoulder, and back"},{"page":"shirt-lesson/index.html","ordinal":124,"anchor":"search-entry-124","zh":"让缝合处平顺","en":"Keep sewn joins smooth","headingZh":"修顺袖窿、肩线和后身","headingEn":"Refine the armhole, shoulder, and back"},{"page":"shirt-lesson/index.html","ordinal":125,"anchor":"search-entry-125","zh":"检查缝合端点的直角","en":"Check right angles at seam endpoints","headingZh":"检查缝合端点的直角","headingEn":"Check right angles at seam endpoints"},{"page":"shirt-lesson/index.html","ordinal":126,"anchor":"search-entry-126","zh":"修改曲线后，放大检查与缝合边相接的端点。端点处尽量形成直角，拼合后的轮廓才不会突然鼓出或凹进去。","en":"After reshaping a curve, zoom in on the point where it joins a sewn edge. Aim for a right angle at the endpoint so the joined outline does not form an abrupt point or dip.","headingZh":"检查缝合端点的直角","headingEn":"Check right angles at seam endpoints"},{"page":"shirt-lesson/index.html","ordinal":127,"anchor":"search-entry-127","zh":"放大袖窿与侧缝等交接处，检查端点附近的线条走向。","en":"Zoom in where the armhole and side seam meet, and inspect the direction of the line near the endpoint.","headingZh":"检查缝合端点的直角","headingEn":"Check right angles at seam endpoints"},{"page":"shirt-lesson/index.html","ordinal":128,"anchor":"search-entry-128","zh":"必要时移动曲线点或调整控制方向，使缝合端点接近 90°，再观察两侧拼合后的线条是否顺畅。","en":"Move a curve point or adjust its handle as needed to bring the seam endpoint close to 90°, then check that the joined edges flow smoothly.","headingZh":"检查缝合端点的直角","headingEn":"Check right angles at seam endpoints"},{"page":"shirt-lesson/index.html","ordinal":129,"anchor":"search-entry-129","zh":"操作视频 · 检查缝合端点","en":"Demonstration · Check seam endpoints","headingZh":"检查缝合端点的直角","headingEn":"Check right angles at seam endpoints"},{"page":"shirt-lesson/index.html","ordinal":130,"anchor":"search-entry-130","zh":"为纽扣留出门襟","en":"Make room for buttons","headingZh":"检查缝合端点的直角","headingEn":"Check right angles at seam endpoints"},{"page":"shirt-lesson/index.html","ordinal":131,"anchor":"search-entry-131","zh":"扩张前中，制作衬衫门襟","en":"Extend the center front for a placket","headingZh":"扩张前中，制作衬衫门襟","headingEn":"Extend the center front for a placket"},{"page":"shirt-lesson/index.html","ordinal":132,"anchor":"search-entry-132","zh":"目前左右前片在前中直接缝在一起。要制作放纽扣的门襟，先删除这条缝线，再向外扩出门襟宽度。","en":"The two front pieces are currently sewn together at the center front. To create a button placket, remove that seam first, then extend the center-front edge outward.","headingZh":"扩张前中，制作衬衫门襟","headingEn":"Extend the center front for a placket"},{"page":"shirt-lesson/index.html","ordinal":133,"anchor":"search-entry-133","zh":"使用「编辑缝纫线」选中前中原有缝线，按 Delete 删除。","en":"Use Edit Sewing to select the existing center-front seam and press Delete to remove it.","headingZh":"扩张前中，制作衬衫门襟","headingEn":"Extend the center front for a placket"},{"page":"shirt-lesson/index.html","ordinal":134,"anchor":"search-entry-134","zh":"切换到「编辑板片」，选中前中边线；右键选择「板片外线扩张」，将间距设为 1.5 cm 后确认。","en":"Switch to Edit Pattern, select the center-front edge, then right-click and choose Offset Pattern Outline. Set the distance to 1.5 cm and confirm.","headingZh":"扩张前中，制作衬衫门襟","headingEn":"Extend the center front for a placket"},{"page":"shirt-lesson/index.html","ordinal":135,"anchor":"search-entry-135","zh":"原来的前中线此时显示为虚线，不能直接按原缝线继续缝纫。按 I 沿这条线点击，按 Enter 结束，在扩出的板片上生成红色内部线。","en":"The former center-front line now appears dashed, so it cannot serve as the original seam. Press I, click along that line, and press Enter to create a red internal line on the extended piece.","headingZh":"扩张前中，制作衬衫门襟","headingEn":"Extend the center front for a placket"},{"page":"shirt-lesson/index.html","ordinal":136,"anchor":"search-entry-136","zh":"操作视频 · 扩张前中并制作门襟","en":"Demonstration · Extend the center front for the placket","headingZh":"扩张前中，制作衬衫门襟","headingEn":"Extend the center front for a placket"},{"page":"shirt-lesson/index.html","ordinal":137,"anchor":"search-entry-137","zh":"让门襟正确叠合","en":"Overlap the placket correctly","headingZh":"扩张前中，制作衬衫门襟","headingEn":"Extend the center front for a placket"},{"page":"shirt-lesson/index.html","ordinal":138,"anchor":"search-entry-138","zh":"叠好前片，再缝合内部线","en":"Overlap the fronts, then sew the internal lines","headingZh":"叠好前片，再缝合内部线","headingEn":"Overlap the fronts, then sew the internal lines"},{"page":"shirt-lesson/index.html","ordinal":139,"anchor":"search-entry-139","zh":"门襟扩出后，先确定左右前片在 3D 中谁盖在上面，再把 2D 工作区里的两条红色内部线缝合。","en":"After extending the placket, decide which front piece overlaps the other in 3D. Then sew the two red internal lines together in the 2D workspace.","headingZh":"叠好前片，再缝合内部线","headingEn":"Overlap the fronts, then sew the internal lines"},{"page":"shirt-lesson/index.html","ordinal":140,"anchor":"search-entry-140","zh":"按空格键开始模拟，轻轻调整前身片，让一侧门襟盖在另一侧上面；再次按空格键暂停。","en":"Press Space to simulate and gently position one front placket over the other. Press Space again to pause.","headingZh":"叠好前片，再缝合内部线","headingEn":"Overlap the fronts, then sew the internal lines"},{"page":"shirt-lesson/index.html","ordinal":141,"anchor":"search-entry-141","zh":"回到 2D 工作区，选择两侧对应的红色内部线，建立缝纫关系。","en":"In the 2D workspace, select the matching red internal lines on both sides and sew them together.","headingZh":"叠好前片，再缝合内部线","headingEn":"Overlap the fronts, then sew the internal lines"},{"page":"shirt-lesson/index.html","ordinal":142,"anchor":"search-entry-142","zh":"重新按空格键模拟，检查门襟的叠合方向和缝合效果。","en":"Press Space to simulate again and check the placket overlap and seam result.","headingZh":"叠好前片，再缝合内部线","headingEn":"Overlap the fronts, then sew the internal lines"},{"page":"shirt-lesson/index.html","ordinal":143,"anchor":"search-entry-143","zh":"操作视频 · 门襟叠合与内部线缝合","en":"Demonstration · Overlap the placket and sew its internal lines","headingZh":"叠好前片，再缝合内部线","headingEn":"Overlap the fronts, then sew the internal lines"},{"page":"shirt-lesson/index.html","ordinal":145,"anchor":"search-entry-145","zh":"领子的制作","en":"MAKING THE COLLAR","headingZh":"叠好前片，再缝合内部线","headingEn":"Overlap the fronts, then sew the internal lines"},{"page":"shirt-lesson/index.html","ordinal":146,"anchor":"search-entry-146","zh":"从领围尺寸开始","en":"Start with the neckline measurement","headingZh":"从领围尺寸开始","headingEn":"Start with the neckline measurement"},{"page":"shirt-lesson/index.html","ordinal":148,"anchor":"search-entry-148","zh":"量半圈，画半片","en":"Measure half, draft half","headingZh":"从领围尺寸开始","headingEn":"Start with the neckline measurement"},{"page":"shirt-lesson/index.html","ordinal":149,"anchor":"search-entry-149","zh":"量领围并建立对称领片","en":"Measure the neckline and draft a symmetric collar","headingZh":"量领围并建立对称领片","headingEn":"Measure the neckline and draft a symmetric collar"},{"page":"shirt-lesson/index.html","ordinal":150,"anchor":"search-entry-150","zh":"领子先从领围长度推算。由于衣身左右对称，只要量一侧的前领圈和后领圈，就能得到半片领子的参考长度。","en":"Start the collar from the neckline length. Because the shirt is symmetric, measuring the front and back neckline on one side gives a reference length for half the collar.","headingZh":"量领围并建立对称领片","headingEn":"Measure the neckline and draft a symmetric collar"},{"page":"shirt-lesson/index.html","ordinal":151,"anchor":"search-entry-151","zh":"用「编辑板片」框选同一侧的前领圈和后领圈线。打开窗口最右侧的「属性编辑器」，查看「2D 线段长度」；示例为 24.99 cm，可取整为 25 cm。","en":"Use Edit Pattern to select the front and back neckline segments on one side. Open the Property Editor at the far right and read 2D Segment Length. The example shows 24.99 cm, rounded to 25 cm.","headingZh":"量领围并建立对称领片","headingEn":"Measure the neckline and draft a symmetric collar"},{"page":"shirt-lesson/index.html","ordinal":152,"anchor":"search-entry-152","zh":"按 S 选择矩形工具，在 2D 空白处双击，输入宽 25 cm、高 5 cm，确认创建半片领子。5 cm 是本次造型示例，可按设计调整。","en":"Press S for Rectangle and double-click an empty area in 2D. Enter 25 cm for width and 5 cm for height to create half the collar. The 5 cm height is this design's example and can be adjusted.","headingZh":"量领围并建立对称领片","headingEn":"Measure the neckline and draft a symmetric collar"},{"page":"shirt-lesson/index.html","ordinal":153,"anchor":"search-entry-153","zh":"选中矩形，按 Ctrl／Command + D 镜像复制关联板片；放到一旁后，用「编辑板片」选中两片的中线，右键「合并」，形成仍可对称联动的完整领片。","en":"Select the rectangle and press Ctrl/Command + D to make a mirrored linked copy. Move it aside, use Edit Pattern to select the center edges, and right-click Merge to form one collar that remains symmetric.","headingZh":"量领围并建立对称领片","headingEn":"Measure the neckline and draft a symmetric collar"},{"page":"shirt-lesson/index.html","ordinal":154,"anchor":"search-entry-154","zh":"在这个基础上大致调整领子的轮廓，稍后再通过模拟检查效果。","en":"Roughly shape the collar outline now; simulation will help you assess it later.","headingZh":"量领围并建立对称领片","headingEn":"Measure the neckline and draft a symmetric collar"},{"page":"shirt-lesson/index.html","ordinal":155,"anchor":"search-entry-155","zh":"操作视频 · 量领围并建立领片","en":"Demonstration · Measure the neckline and draft the collar","headingZh":"量领围并建立对称领片","headingEn":"Measure the neckline and draft a symmetric collar"},{"page":"shirt-lesson/index.html","ordinal":158,"anchor":"search-entry-158","zh":"从后中走到前中","en":"Sew from center back to center front","headingZh":"量领围并建立对称领片","headingEn":"Measure the neckline and draft a symmetric collar"},{"page":"shirt-lesson/index.html","ordinal":159,"anchor":"search-entry-159","zh":"用 M:N 自由缝连接领子与领圈","en":"Attach the collar with M:N Free Sewing","headingZh":"用 M:N 自由缝连接领子与领圈","headingEn":"Attach the collar with M:N Free Sewing"},{"page":"shirt-lesson/index.html","ordinal":160,"anchor":"search-entry-160","zh":"先把领子缝到衣身上，看看长度与形状是否合适。这一步的选线顺序很重要，建议跟着视频逐段点选。","en":"Sew the collar to the shirt to test its length and shape. The order of selected segments matters here, so follow the recording one segment at a time.","headingZh":"用 M:N 自由缝连接领子与领圈","headingEn":"Attach the collar with M:N Free Sewing"},{"page":"shirt-lesson/index.html","ordinal":161,"anchor":"search-entry-161","zh":"选择「M:N 自由缝纫」。从领片中线选到一侧端点，按 Enter 确认 M 线。","en":"Choose M:N Free Sewing. Select from the collar's center line to one end, then press Enter to confirm the M side.","headingZh":"用 M:N 自由缝连接领子与领圈","headingEn":"Attach the collar with M:N Free Sewing"},{"page":"shirt-lesson/index.html","ordinal":162,"anchor":"search-entry-162","zh":"接着选择衣身的后领圈作为 N 的第一段，再接着选前领圈作为第二段：路径是后中 → 后领圈 → 越过肩线 → 前领圈 → 前中。最后按 Enter 结束 N 线。","en":"For the N side, select the back neckline first and the front neckline second. Follow center back → back neckline → across the shoulder seam → front neckline → center front, then press Enter to finish N.","headingZh":"用 M:N 自由缝连接领子与领圈","headingEn":"Attach the collar with M:N Free Sewing"},{"page":"shirt-lesson/index.html","ordinal":163,"anchor":"search-entry-163","zh":"在 3D 窗口检查彩色缝纫线是否按这个方向连接；确认后选中领片，右键「硬化」，按空格键模拟。","en":"Check the colored sewing lines in 3D to confirm their direction. Then select the collar piece, right-click Harden, and press Space to simulate.","headingZh":"用 M:N 自由缝连接领子与领圈","headingEn":"Attach the collar with M:N Free Sewing"},{"page":"shirt-lesson/index.html","ordinal":164,"anchor":"search-entry-164","zh":"操作视频 · 缝合并模拟领子","en":"Demonstration · Sew and simulate the collar","headingZh":"用 M:N 自由缝连接领子与领圈","headingEn":"Attach the collar with M:N Free Sewing"},{"page":"shirt-lesson/index.html","ordinal":165,"anchor":"search-entry-165","zh":"调整领片的转折","en":"Refine the collar shape","headingZh":"用 M:N 自由缝连接领子与领圈","headingEn":"Attach the collar with M:N Free Sewing"},{"page":"shirt-lesson/index.html","ordinal":166,"anchor":"search-entry-166","zh":"移动旋转中心，修出领圈弧度","en":"Move the pivot and shape the collar curve","headingZh":"移动旋转中心，修出领圈弧度","headingEn":"Move the pivot and shape the collar curve"},{"page":"shirt-lesson/index.html","ordinal":167,"anchor":"search-entry-167","zh":"领片缝上后，再按肩部的位置调整它的角度与下缘曲线。先找到领片一侧下角与对应方向中线的对齐位置，作为旋转基准。","en":"After sewing the collar on, adjust its angle and lower curve around the shoulder. First align one lower collar corner with the center reference line on the corresponding side to establish a pivot.","headingZh":"移动旋转中心，修出领圈弧度","headingEn":"Move the pivot and shape the collar curve"},{"page":"shirt-lesson/index.html","ordinal":168,"anchor":"search-entry-168","zh":"选中领片，把一侧底角对齐到对应方向的中线；可以参考红色内部线，也可以参考最外侧的边线。","en":"Select the collar and align one lower corner with the center line on that side. Either the red internal line or the outermost edge can serve as the reference.","headingZh":"移动旋转中心，修出领圈弧度","headingEn":"Move the pivot and shape the collar curve"},{"page":"shirt-lesson/index.html","ordinal":169,"anchor":"search-entry-169","zh":"双击旋转中心将其激活，再把旋转中心移到刚对齐的角上。旋转领片，让领片下缘落在肩线往里约 1–2 cm 的位置。","en":"Double-click to activate the rotation pivot, move it to the aligned corner, then rotate the collar until its lower edge falls about 1–2 cm inside the shoulder line.","headingZh":"移动旋转中心，修出领圈弧度","headingEn":"Move the pivot and shape the collar curve"},{"page":"shirt-lesson/index.html","ordinal":170,"anchor":"search-entry-170","zh":"用「编辑曲线点」修出领圈附近顺畅的弧线，按空格键模拟检查。","en":"Use Edit Curve Point to smooth the curve near the neckline, then press Space to simulate and inspect it.","headingZh":"移动旋转中心，修出领圈弧度","headingEn":"Move the pivot and shape the collar curve"},{"page":"shirt-lesson/index.html","ordinal":171,"anchor":"search-entry-171","zh":"操作视频 · 调整领片角度与领圈弧度","en":"Demonstration · Adjust the collar angle and neckline curve","headingZh":"移动旋转中心，修出领圈弧度","headingEn":"Move the pivot and shape the collar curve"},{"page":"shirt-lesson/index.html","ordinal":172,"anchor":"search-entry-172","zh":"把 3D 标记带回 2D","en":"Bring a 3D mark into 2D","headingZh":"移动旋转中心，修出领圈弧度","headingEn":"Move the pivot and shape the collar curve"},{"page":"shirt-lesson/index.html","ordinal":173,"anchor":"search-entry-173","zh":"画出领子的翻折线","en":"Draw the collar fold line","headingZh":"画出领子的翻折线","headingEn":"Draw the collar fold line"},{"page":"shirt-lesson/index.html","ordinal":174,"anchor":"search-entry-174","zh":"先在 3D 服装上判断翻折线应该落在哪里，再把位置同步回 2D 板片，结合 2D 内部线与 3D 笔勾勒整条曲线。","en":"Decide where the collar should fold on the 3D garment. Transfer that position to the 2D piece, then combine a 2D internal line with a 3D pen stroke to define the full curve.","headingZh":"画出领子的翻折线","headingEn":"Draw the collar fold line"},{"page":"shirt-lesson/index.html","ordinal":175,"anchor":"search-entry-175","zh":"在 3D 窗口点击预计的翻折终点；出现的蓝色点也会同步显示在 2D 板片上。按 X 在线上加点，再按 G 从该点向领圈画一段内部线。","en":"Click the intended fold endpoint in 3D. Its blue marker also appears on the 2D piece. Press X to add a point on the line, then G to draw an internal line from that point toward the neckline.","headingZh":"画出领子的翻折线","headingEn":"Draw the collar fold line"},{"page":"shirt-lesson/index.html","ordinal":176,"anchor":"search-entry-176","zh":"选择「3D 笔（服装）」，从后中沿领子画到刚添加的线。少量点即可；双击结束，或再次点击选择工具退出。","en":"Choose 3D Pen (Garment) and draw from center back across the collar to the line you just added. A few points are enough; double-click to finish or return to the selection tool.","headingZh":"画出领子的翻折线","headingEn":"Draw the collar fold line"},{"page":"shirt-lesson/index.html","ordinal":177,"anchor":"search-entry-177","zh":"切换到「编辑 3D 画笔（服装）」，选中线条，右键选择「转化为内部图形」。2D 板片上会出现对应的内部线；可用「生成圆顺曲线」再把轮廓修顺。","en":"Switch to Edit 3D Pen (Garment), select the stroke, and right-click Convert to Internal Shape. The corresponding internal line appears on the 2D piece; use Smooth Curve to refine it if needed.","headingZh":"画出领子的翻折线","headingEn":"Draw the collar fold line"},{"page":"shirt-lesson/index.html","ordinal":178,"anchor":"search-entry-178","zh":"操作视频 · 绘制并转化翻折线","en":"Demonstration · Draw and convert the fold line","headingZh":"画出领子的翻折线","headingEn":"Draw the collar fold line"},{"page":"shirt-lesson/index.html","ordinal":179,"anchor":"search-entry-179","zh":"让领子翻下来","en":"Let the collar fold down","headingZh":"画出领子的翻折线","headingEn":"Draw the collar fold line"},{"page":"shirt-lesson/index.html","ordinal":180,"anchor":"search-entry-180","zh":"设置翻折强度并调整缝纫点","en":"Set fold strength and reposition the seam points","headingZh":"设置翻折强度并调整缝纫点","headingEn":"Set fold strength and reposition the seam points"},{"page":"shirt-lesson/index.html","ordinal":181,"anchor":"search-entry-181","zh":"翻折线已变成领片上的内部线。为这条线设置折叠属性，再让中线缝纫点与翻折位置对齐，领子才能在模拟时自然翻下。","en":"The fold guide is now an internal line on the collar. Give it a fold setting and align the center seam points with the fold so the collar turns down during simulation.","headingZh":"设置翻折强度并调整缝纫点","headingEn":"Set fold strength and reposition the seam points"},{"page":"shirt-lesson/index.html","ordinal":182,"anchor":"search-entry-182","zh":"在 2D 工作区用「编辑点／线」选择需要翻折的内部线。按住 Shift 可多选线段；只需选择半边，对称关联会同步另一侧。","en":"In 2D, use Edit Point/Line to select the internal segments that should fold. Hold Shift to select several segments. Select only one half; the linked side updates symmetrically.","headingZh":"设置翻折强度并调整缝纫点","headingEn":"Set fold strength and reposition the seam points"},{"page":"shirt-lesson/index.html","ordinal":183,"anchor":"search-entry-183","zh":"打开右侧「属性编辑器」，将所选内部线的「折叠强度」设为 100。","en":"Open the Property Editor at the right and set Fold Strength for the selected internal line to 100.","headingZh":"设置翻折强度并调整缝纫点","headingEn":"Set fold strength and reposition the seam points"},{"page":"shirt-lesson/index.html","ordinal":184,"anchor":"search-entry-184","zh":"按 B 使用「编辑缝纫线」，分别选中领片中线两侧的缝纫点，向下移到与翻折点大致同一水平。点位较小，可放大视图耐心选取；两侧都要调整。","en":"Press B for Edit Sewing. On both sides of the collar center seam, select the seam points and move them down to roughly the height of the fold points. Zoom in and take time with these small targets; adjust both sides.","headingZh":"设置翻折强度并调整缝纫点","headingEn":"Set fold strength and reposition the seam points"},{"page":"shirt-lesson/index.html","ordinal":185,"anchor":"search-entry-185","zh":"按空格键模拟，在 3D 工作区轻轻调整领子，检查翻折后的形状。","en":"Press Space to simulate, gently adjust the collar in 3D, and inspect its folded shape.","headingZh":"设置翻折强度并调整缝纫点","headingEn":"Set fold strength and reposition the seam points"},{"page":"shirt-lesson/index.html","ordinal":186,"anchor":"search-entry-186","zh":"操作视频 · 设置翻折并调整领子","en":"Demonstration · Set the fold and finish the collar","headingZh":"设置翻折强度并调整缝纫点","headingEn":"Set fold strength and reposition the seam points"},{"page":"shirt-lesson/index.html","ordinal":188,"anchor":"search-entry-188","zh":"领片的弧度、翻折线与中线缝纫位置都已调整好。模拟后从正面、侧面和背面检查领子的翻折与贴合，再按自己的衬衫造型继续微调。","en":"The collar curve, fold line, and center seam positions are now set. Simulate and inspect the collar from the front, side, and back, then refine the fold and fit to suit your shirt design.","headingZh":"设置翻折强度并调整缝纫点","headingEn":"Set fold strength and reposition the seam points"}];
